import {additionalTutorFamilies,number} from './additional-tutor-families.mjs';

const perFamily=20000;
const perColumn=200;
const total=perFamily*additionalTutorFamilies.length;
const prefix='tutor-extra-';
const courses=[...new Set(additionalTutorFamilies.map(family=>family.course))];
const normalize=value=>String(value).toLowerCase().normalize('NFKD').replace(/\p{M}/gu,'')
  .replace(/[’']/g,'').replace(/[^a-z0-9]+/g,' ').trim();
const bounded=(text,part)=>(' '+text+' ').includes(' '+part+' ');
const families=additionalTutorFamilies.map((family,index)=>({...family,start:index*perFamily,aliases:[family.id,family.title,...family.aliases].map(normalize)}));
const formatAnswer=(value,unit)=>unit.startsWith('%')?number(value)+unit:unit==='pH'?'pH '+number(value):number(value)+' '+unit;

export const additionalTutorManifest=()=>({
  total,families:families.map(({id,title,course,start,link})=>({id,title,course,start,count:perFamily,link})),
  perCourse:Object.fromEntries(courses.map(course=>[course,families.filter(family=>family.course===course).length*perFamily])),
  answeredFollowupsPerScenario:12,
  approach:'Original numerical practice families with deterministic variants'
});

function materialize(index){
  if(!Number.isInteger(index)||index<0||index>=total)return null;
  const family=families[Math.floor(index/perFamily)];
  const local=index-family.start;
  const row=family.build(1+local%perColumn,1+Math.floor(local/perColumn));
  return {family,row};
}

export function inspectAdditionalTutorScenario(index){
  const build=materialize(index);
  if(!build)return null;
  return {familyId:build.family.id,...build.row};
}

const followupQuestions=[
  ['Find the target','What is this question asking me to find?'],
  ['Pick the givens','Which givens should I keep?'],
  ['Choose a formula','Which formula or relationship applies here?'],
  ['Give a hint','Can I have a first-step hint?'],
  ['Why this method?','Why does this approach work here?'],
  ['Trace the numbers','Where did the first number in your work come from?'],
  ['Show worked solution','Can you show the worked calculation?'],
  ['Check the units','How do I read or cancel the units?'],
  ['Avoid a common error','What is a common mistake with this problem?'],
  ['Check the result','How do I tell if the result makes sense?'],
  ['Try another approach','Is there another way to set this up?'],
  ['Change a given','How would the result change if one input changed?']
];

export function additionalTutorScenario(index){
  const build=materialize(index);
  if(!build)return null;
  const {family,row}=build;
  const answer=formatAnswer(row.value,row.unit);
  const responses=[
    row.target,row.givens,row.formula+' '+row.why,row.steps[0],row.why,
    row.steps[0]+' The quantities come from these givens. '+row.givens,
    [...row.steps,'Result '+answer+'.'].join(' '),
    row.steps.at(-1)+' Report '+(row.unit==='pH'?'pH without a physical unit.':'the result in '+row.unit+'.'),
    row.mistake,row.check??'Use '+answer+' to work backward with the same relationship. Your check should recover the stated values. '+row.givens,
    row.alternate,row.transfer
  ];
  return {
    id:prefix+String(index+1).padStart(6,'0'),index,course:family.course,topic:family.id,title:family.title,
    question:row.question,text:row.why,formula:row.formula,givens:row.givens,target:row.target,
    steps:row.steps,answer,value:row.value,unit:row.unit,links:[family.link],
    followups:followupQuestions.map(([,question],i)=>({question,answer:responses[i]}))
  };
}

const scenarioActions=scenario=>followupQuestions.map(([label,question],index)=>[label,scenario.id+' followup '+(index+1),question]);
const menuPrompt='Show additional tutor topics';
function matchesCourse(value){
  const query=normalize(value).replace(/\b(biol|chem)(?=\d)/g,'$1 ');
  return courses.find(course=>bounded(query,normalize(course)))??'';
}
function matchFamily(raw,course){
  const query=normalize(raw);
  const candidates=families.filter(family=>!course||family.course===course).map(family=>({
    family,score:Math.max(...family.aliases.filter(alias=>bounded(query,alias)).map(alias=>alias.length),0)
  })).sort((a,b)=>b.score-a.score);
  if(!candidates[0]?.score)return null;
  if(candidates[0].score===candidates[1]?.score)return null;
  return candidates[0].family;
}
function menu(course){
  const choices=course?families.filter(family=>family.course===course):[];
  return {
    topic:'additional-tutor',intent:'source',
    text:course?'Choose a '+course+' tutoring scenario. Each one has a worked solution and 12 follow-up explanations.':
      'Choose a course to see the additional tutoring scenarios. They are original practice examples.',
    actions:course?choices.map(family=>[family.title,'Additional tutor practice '+family.id+' '+family.course]):
      courses.map(name=>[name,menuPrompt+' '+name]),
    links:[]
  };
}
function opensScenario(scenario){
  return {
    topic:scenario.topic,intent:'practice',title:scenario.title,course:scenario.course,scenarioId:scenario.id,
    text:scenario.question,question:'What quantity is the problem asking for, and what would you do first?',
    links:scenario.links,actions:[...scenarioActions(scenario),['Try another version',scenario.id+' another','Can I try another version of this example?']]
  };
}
function answerScenario(scenario,index){
  const response=scenario.followups[index];
  if(index===6)return {
    topic:scenario.topic,intent:'worked',title:scenario.title,course:scenario.course,scenarioId:scenario.id,text:'Here’s the calculation for this example.',
    formula:scenario.formula,steps:scenario.steps,answer:scenario.answer,links:scenario.links,actions:scenarioActions(scenario)
  };
  return {
    topic:scenario.topic,intent:index===3?'hint':'followup',title:scenario.title,course:scenario.course,scenarioId:scenario.id,
    text:response.answer,links:scenario.links,actions:scenarioActions(scenario)
  };
}
const exactFollowups=followupQuestions.map(([,question])=>normalize(question));
const followupPatterns=[
  /\b(?:target|what (?:is|s|does) (?:it|this|the question) ask|what is it asking)\b/,
  /\b(?:givens?|which (?:values|numbers) (?:matter|do i use)|what information)\b/,
  /\b(?:formula|equation|relationship)\b/,
  /\bhint\b|\bwhat (?:should|do) i do first\b/,
  /\bwhy\b.*\b(?:method|approach|works?)\b/,
  /\b(?:where|how)\b.*\b(?:get|come from|came from)\b/,
  /\b(?:worked|show (?:me )?(?:(?:your|the) )?(?:work|calculation|answer|solution)|what (?:is|s) the answer|solve it|finish the example)\b/,
  /\b(?:cancel|units?|dimensions?)\b/,
  /\b(?:mistake|common error|trap)\b/,
  /\b(?:does it make sense|check (?:the answer|the result|my work|my answer)|tell if the result)\b/,
  /\b(?:another way|different way|another approach|second method|alternative setup)\b/,
  /\b(?:change a given|one input changed|transfer example)\b/
];
const menuRequest=/\b(?:additional|expanded|new)\s+(?:tutor|tutoring)\s+(?:topics|bank|menu|scenarios)\b/;
const addedPractice=/\b(?:additional|expanded|new)\s+(?:tutor|tutoring)\s+(?:practice|example|scenario|question)\b/;
const naturalPractice=/^(?:(?:can|could|would) (?:i|you) |please )?(?:let me |help me |give me (?:an?|some) |show me (?:an?|some) )?(?:practice(?: scenario| problem| question)?|worked example|example question) (?:for |about |of |on |with )?/;

export function createAdditionalTutor(){
  let active=null,position=0;
  const visits=new Map();
  function reset(){
    active=null;
    position=0;
    visits.clear();
  }
  function open(index){
    active=additionalTutorScenario(index);
    position=0;
    return active?opensScenario(active):null;
  }
  function sample(family){
    const count=visits.get(family.id)??0;
    visits.set(family.id,count+1);
    // Coprime to the family size so repeated requests traverse distinct variants.
    return open(family.start+(count*1117)%perFamily);
  }
  function nextVariant(scenario){
    const start=Math.floor(scenario.index/perFamily)*perFamily;
    return open(start+(scenario.index-start+1117)%perFamily);
  }
  function respond(raw,course=''){
    const text=String(raw??'').trim();
    const query=normalize(text);
    if(!query||/^(?:new topic|new problem|start over)$/.test(query)){
      reset();
      return null;
    }
    const chosen=matchesCourse(query)||matchesCourse(course);
    const keyed=query.match(/^tutor extra (\d{1,6})(?: (?:followup (\d{1,2})|(another)))?$/);
    if(keyed){
      const index=Number(keyed[1])-1;
      const entry=open(index);
      if(!entry)return {topic:'additional-tutor',intent:'clarify',text:'Use a tutoring scenario number from 1 through '+number(total)+'.',actions:[['See topics',menuPrompt]]};
      if(keyed[3])return nextVariant(active);
      if(keyed[2]&&Number(keyed[2])>=1&&Number(keyed[2])<=12)return answerScenario(active,Number(keyed[2])-1);
      return entry;
    }
    if(menuRequest.test(query)||/^additional tutor$/.test(query))return menu(chosen);
    const another=/\b(?:another|different)\b.*\b(?:additional tutor|tutoring scenario)\b/.test(query);
    if(another&&active)return nextVariant(active);
    if(addedPractice.test(query)||naturalPractice.test(query)){
      const family=matchFamily(query,chosen);
      if(family){
        const response=sample(family);
        return /\bworked example\b/.test(query)?{...answerScenario(active,6),text:active.question}:response;
      }
      if(addedPractice.test(query))return menu(chosen);
    }
    if(!active||chosen&&chosen!==active.course)return null;
    const exact=exactFollowups.indexOf(query);
    if(exact>=0)return answerScenario(active,exact);
    const referencedFamily=matchFamily(query,'');
    if(referencedFamily&&referencedFamily.id!==active.topic){
      active=null;
      return null;
    }
    if(/^(?:next step|whats next|what is next|then what|go on|next)$/.test(query)){
      if(position>=active.steps.length)return answerScenario(active,6);
      return {topic:active.topic,intent:'hint',title:active.title,course:active.course,scenarioId:active.id,text:active.steps[position++],links:active.links,actions:scenarioActions(active)};
    }
    const simple=/^(?:why|i dont (?:get it|understand)|(?:can you )?break (?:it|this|that) down|explain it simply)$/.test(query);
    if(simple)return answerScenario(active,4);
    if(/^(?:another way|a different method|another approach|different way)$/.test(query))return answerScenario(active,10);
    const mention=/^(?:where|how)\b.*\b(?:get|come from)\b/i.test(text)
      ?text.match(/(?<![\p{L}\p{N}])((?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?)(?![\p{L}\p{N}])/u)?.[1]:null;
    if(mention){
      const expression=new RegExp('(?<![0-9.,])'+mention.replace('.','\\.')+'(?![0-9.,])');
      const detail=active.steps.find(entry=>expression.test(entry));
      if(detail)return {topic:active.topic,intent:'followup',title:active.title,course:active.course,scenarioId:active.id,text:detail,links:active.links,actions:scenarioActions(active)};
    }
    const guess=text.match(/^i (?:got|found|think it(?:’s|'s| is)) ([+−-]?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?)\.?$/i)?.[1];
    if(guess){
      const value=Number(guess.replaceAll(',','').replaceAll('−','-'));
      const fits=Math.abs(active.value-value)<=5e-6+Math.abs(active.value)*1e-6;
      return {topic:active.topic,intent:'followup',title:active.title,course:active.course,scenarioId:active.id,text:fits?'That agrees with the calculation. Check the unit and round as your question requests.':
        'Try checking this step before you round. '+active.steps.at(-1),links:active.links,actions:scenarioActions(active)};
    }
    if(query.split(' ').length<=15&&/^(?:can|could|would|what|which|where|how|why|show|is|give|solve|help|check|try)\b/.test(query)){
      const derived=followupPatterns.findIndex(pattern=>pattern.test(query));
      const asksAnotherTopic=/\b(?:for|about) (?!this\b|that\b|the (?:same|problem|question|example)\b|me\b)/.test(query);
      if(asksAnotherTopic){active=null;return null;}
      if(derived>=0&&(/\b(?:your|the|this|here|my|that)\b/.test(query)||query.split(' ').length<=8))return answerScenario(active,derived);
    }
    return null;
  }
  return {respond,reset};
}

const decimal=new Intl.NumberFormat('en-US',{maximumFractionDigits:6});
export const number=value=>value!==0&&(Math.abs(value)<1e-5||Math.abs(value)>=1e9)
  ?value.toExponential(6):decimal.format(value);
const n=number;
const close=(actual,expected)=>Number.isFinite(actual)&&Number.isFinite(expected)&&Math.abs(actual-expected)<=1e-10*Math.max(1,Math.abs(expected));
const family=(course,id,title,section,aliases,build)=>({
  course,id,title,aliases:aliases.split(';'),build,
  link:['OpenStax '+(course.startsWith('BIOL')?'Biology':'Chemistry')+' 2e · '+title,
    'https://openstax.org/books/'+(course.startsWith('BIOL')?'biology':'chemistry')+'-2e/pages/'+section]
});
const bioOne=(...args)=>family('BIOL 1406',...args);
const bioTwo=(...args)=>family('BIOL 1407',...args);
const chemFive=(...args)=>family('CHEM 1405',...args);
const chemSix=(...args)=>family('CHEM 1406',...args);
const chemOne=(...args)=>family('CHEM 1411',...args);

export const additionalTutorFamilies=[
  bioOne('image-scale-bar','Calibrate a microscope image with a scale bar','4-1-studying-cells','microscope scale bar;calibrated image;pixels to micrometers;microscopy',(x,y)=>{
    const reference=40+x, measured=60+y, value=25*measured/reference;
    return {
      question:`A microscope image contains a 25 µm scale bar that spans ${reference} pixels. An organelle in the same image spans ${measured} pixels. How long is the organelle in micrometers?`,
      givens:`Scale bar ${reference} pixels for 25 µm. Organelle ${measured} pixels.`,target:'The organelle’s actual length in µm.',
      formula:'Actual length = measured pixels × (physical length of scale bar ÷ scale-bar pixels).',
      steps:[`Find the calibration factor: 25 µm ÷ ${reference} px.`,`Multiply ${measured} px by (25 µm ÷ ${reference} px). Pixels cancel.`],
      value,unit:'µm',verify:close(value*reference/measured,25),
      why:'Both distances were measured in the same image. Each pixel represents the same physical length.',
      mistake:'Do not divide by 25 as if the bar were 25 pixels. The given 25 is its physical length in µm.',
      alternate:`Set up the proportion L ÷ 25 µm = ${measured} ÷ ${reference}. Solve for L.`,
      transfer:`If the organelle spanned twice as many pixels with the same scale bar, its length would be ${n(2*value)} µm.`
    };
  }),
  bioOne('enzyme-interval','Find enzyme product rate over an interval','6-5-enzymes','enzyme rate;enzyme activity;product rate;enzyme interval',(x,y)=>{
    const initial=5+x, time=15+y, final=initial+12+2*y, value=(final-initial)/time;
    return {
      question:`An enzyme reaction has ${initial} µmol of product at 10 s and ${final} µmol at ${10+time} s. What is the average product formation rate between those measurements?`,
      givens:`First point (${10} s, ${initial} µmol). Second point (${10+time} s, ${final} µmol).`,target:'Average formation rate across the measured interval, in µmol/s.',
      formula:'Average rate = (later product − earlier product) ÷ (later time − earlier time).',
      steps:[`Product change is ${final} − ${initial} = ${final-initial} µmol.`,`Elapsed time is ${10+time} − 10 = ${time} s. Divide the product change by this interval.`],
      value,unit:'µmol/s',verify:close(initial+time*value,final),
      why:'The sample already contains product at the first measurement. Look at the increase during the specified interval.',
      mistake:'Dividing the last reading by the last timestamp would count product made before 10 s.',
      alternate:`Read the two points on a plot of product against time. The slope of the connecting line is the rise ${final-initial} µmol over the run ${time} s.`,
      transfer:`If the same increase took twice as long, the average rate would be ${n(value/2)} µmol/s.`
    };
  }),
  bioOne('osmotic-start-mass','Recover starting mass from an osmosis result','5-2-passive-transport','osmosis percent change;start mass;potato osmosis;tonicity calculation',(x,y)=>{
    const final=(200+x)/100, signed=(y-50)/10, fraction=1+signed/100, value=final/fraction;
    return {
      question:`A model potato piece finishes an osmosis observation at ${final.toFixed(2)} g. Its signed mass change is ${signed.toFixed(1)}% relative to its starting mass. What was its starting mass?`,
      givens:`Final mass ${final.toFixed(2)} g. Signed change ${signed.toFixed(1)}% relative to the starting mass.`,target:'Starting mass before the observation, in g.',
      formula:'Starting mass = final mass ÷ [1 + (signed percent change ÷ 100)].',
      steps:[`Change ${signed.toFixed(1)}% to a signed fraction by dividing by 100.`,`The final mass is ${n(fraction)} times the starting mass. Divide ${final.toFixed(2)} g by that factor.`],
      value,unit:'g',verify:close(100*(final-value)/value,signed),
      why:'The percentage is based on the starting mass, so reverse the scale factor to recover that starting value.',
      mistake:'Do not use final mass as the reference amount for the percentage.',
      alternate:`Let m be the starting mass. Set (${final.toFixed(2)} − m) ÷ m = ${n(signed/100)}, then solve for m.`,
      transfer:`If the mass change were 0% and the final mass were still ${final.toFixed(2)} g, the starting mass would equal ${final.toFixed(2)} g.`
    };
  }),
  bioOne('gross-photosynthesis','Separate net oxygen gain from gross oxygen production','8-1-overview-of-photosynthesis','gross photosynthesis;net photosynthesis;oxygen in photosynthesis;oxygen production',(x,y)=>{
    const net=20+x, used=4+y, value=net+used;
    return {
      question:`In a teaching model, an illuminated leaf’s chamber gains ${net} µmol O₂ in an hour. During the same hour respiration uses ${used} µmol O₂. How much O₂ did photosynthesis produce before subtracting respiration?`,
      givens:`Net O₂ gain ${net} µmol. Respiratory O₂ use ${used} µmol during the same hour.`,target:'Total oxygen produced by photosynthesis during the hour, in µmol.',
      formula:'Gross O₂ produced = net O₂ gained + O₂ used.',
      steps:[`Write net gain = gross production − respiration. The net reading is already after oxygen use.`,`Add ${net} µmol and ${used} µmol.`],
      value,unit:'µmol O₂',verify:value-used===net,
      why:'Photosynthesis puts O₂ into the balance while respiration takes it out. The chamber change reflects both.',
      mistake:'Subtracting respiration a second time would underestimate gross production.',
      alternate:`Write a chamber ledger with ${net} µmol left and ${used} µmol used. The two amounts together account for the photosynthetic output.`,
      transfer:`If O₂ use stayed at ${used} µmol but the net gain were zero, gross output would still be ${used} µmol.`
    };
  }),
  bioOne('rna-exon-length','Estimate mature mRNA length from retained exons','15-4-rna-processing-in-eukaryotes','rna splicing;mrna length;exon count;intron length;exons and introns',(x,y)=>{
    const exonA=120+x, exonB=70+y, intron=140+x+y, value=exonA+exonB;
    return {
      question:`A simple eukaryotic pre-mRNA diagram shows exons of ${exonA} and ${exonB} nucleotides separated by a ${intron}-nucleotide intron. If the intron is removed and both exons are kept, how long is the joined RNA before added end modifications are counted?`,
      givens:`Exons ${exonA} and ${exonB} nt. Removed intron ${intron} nt. Exclude added end modifications.`,target:'Number of nucleotides in the two joined exons.',
      formula:'Joined exon length = length of exon 1 + length of exon 2.',
      steps:[`Identify the two portions kept after splicing: ${exonA} nt and ${exonB} nt.`,`Add those lengths. Leave out the removed ${intron} nt.`],
      value,unit:'nt',verify:value+intron===exonA+intron+exonB,
      why:'Splicing can remove an intron without removing the retained exons. The question asks about RNA length, so untranslated exon regions still count.',
      mistake:'Do not divide by three. This question asks for nucleotides, not a peptide length.',
      alternate:`Start from all ${exonA+intron+exonB} nt in the diagram, then subtract the ${intron} nt removed by splicing.`,
      transfer:`Doubling only the intron length leaves the joined RNA at ${value} nt if the same exons are retained.`
    };
  }),
  bioTwo('tagged-sample-estimate','Estimate population size by mark–recapture','45-1-population-demography','mark recapture;mark and recapture;lincoln petersen;population estimate',(x,y)=>{
    const marked=80+x, captured=110+y, found=22, value=marked*captured/found;
    return {
      question:`A wildlife survey marks and releases ${marked} beetles. A later sample contains ${captured} beetles, including ${found} marks. Under the simple closed-population mark–recapture model, estimate the population size.`,
      givens:`Initially marked ${marked}. Later caught ${captured}. Marked in the later sample ${found}.`,target:'Estimated number of beetles in the population.',
      formula:'Estimated total = initially marked × size of second sample ÷ marked recaptures.',
      steps:[`The marked fraction in the second sample is ${found} ÷ ${captured}.`,`Set the total population’s marked fraction equal to this. Calculate ${marked} × ${captured} ÷ ${found}.`],
      value,unit:'estimated beetles',verify:close(marked/value,found/captured),
      why:'If marks are retained, marked animals mix, and capture is comparable, the sample marked fraction estimates the population fraction.',
      mistake:'Use the number of marked beetles found again as the divisor. The second sample includes both marked and unmarked beetles.',
      alternate:`Solve ${marked} ÷ N = ${found} ÷ ${captured} for N.`,
      transfer:`If twice as many marks appeared in the same-sized second sample, the model estimate would fall to ${n(value/2)} beetles.`
    };
  }),
  bioTwo('xylem-water-potential-gap','Compare water potential in two plant cells','30-5-transport-of-water-and-solutes-in-plants','water potential;solute potential;pressure potential;plant water comparison',(x,y)=>{
    const a=-0.9-x/1000, b=-0.3-y/1000, p=0.18, q=0.06, totalA=a+p,totalB=b+q,value=totalB-totalA;
    return {
      question:`Cell A has solute potential ${a.toFixed(3)} MPa and pressure potential 0.180 MPa. Cell B has solute potential ${b.toFixed(3)} MPa and pressure potential 0.060 MPa. Ignoring gravity and matric effects, how much higher is B’s water potential than A’s, and which way will water move if the cells exchange water?`,
      givens:`Cell A has ${a.toFixed(3)} MPa solute and 0.180 MPa pressure. Cell B has ${b.toFixed(3)} MPa solute and 0.060 MPa pressure.`,target:'Water-potential gap in MPa and the net direction of flow.',
      formula:'Ψ = Ψsolute + Ψpressure. Water moves from higher Ψ toward lower Ψ.',
      steps:[`Add within each cell. A = ${n(totalA)} MPa. B = ${n(totalB)} MPa.`,`Subtract A from B to get the difference. Because B has the higher water potential, net movement is from B toward A.`],
      value,unit:'MPa higher in B, with net flow B → A',verify:close(totalA+value,totalB)&&value>0,
      why:'Pressure and solutes can both affect the tendency of water to move. Add the signed terms before comparing.',
      mistake:'Keep the negative signs on solute potential. A less negative water potential is higher.',
      alternate:`Subtract the components first. (Ψsolute B − Ψsolute A) + (0.060 − 0.180) MPa gives the same B-minus-A gap.`,
      transfer:`If A’s pressure increased by 0.050 MPa alone, the gap would shrink to ${n(value-0.05)} MPa.`
    };
  }),
  bioTwo('conditional-survivorship','Calculate conditional survival between two ages','45-1-population-demography','conditional survival;life table;survivorship;cohort survival',(x,y)=>{
    const n0=241+x+y, early=130+x, late=25+y, value=100*late/early;
    return {
      question:`An ecological life table follows ${n0} hatchlings. ${early} reach age one and ${late} reach age two. Among animals that reached age one, what percentage survive to age two?`,
      givens:`Hatchlings ${n0}. Alive at age one ${early}. Alive at age two ${late}.`,target:'Age-two survival conditional on reaching age one, as a percentage.',
      formula:'Conditional survival = age-two survivors ÷ age-one survivors × 100%.',
      steps:[`Use ${early} as the denominator, because the question starts with age-one survivors.`,`Divide ${late} by ${early} and multiply by 100.`],
      value,unit:'%',verify:close(value/100*early,late)&&late<=early&&early<=n0,
      why:'The word “among” identifies the group already present at the beginning of the interval we are studying.',
      mistake:`Using ${n0} gives survival from hatching to age two, which is a different probability.`,
      alternate:`Subtract the ${early-late} animals lost during the interval from the ${early} at its start, then divide the survivors by ${early}.`,
      transfer:`If all ${early} age-one animals survived to age two, the conditional percentage would be 100%.`
    };
  }),
  bioTwo('net-ecological-rate','Convert census changes to a net weekly rate','45-3-environmental-limits-to-population-growth','population change rate;net population growth;weekly growth rate;census change',(x,y)=>{
    const start=290+x, weeks=2+y, end=start+60-y, value=(end-start)/weeks;
    return {
      question:`A wildlife census reports ${start} animals at the first count and ${end} animals ${weeks} weeks later. What is the average net change in animals per week over this interval?`,
      givens:`Initial count ${start}. Final count ${end}. Elapsed time ${weeks} weeks.`,target:'Average signed difference per week, in animals/week.',
