const abs = value => value < 0n ? -value : value;
const sign = value => value < 0n ? -1 : value > 0n ? 1 : 0;
function gcd(a,b) {
  a=abs(a); b=abs(b);
  while(b) [a,b]=[b,a%b];
  return a||1n;
