  let text=normalizeMath(input).replace(/[?!]+$/,'').trim();
  const onlyReal=/\b(?:over|in) the reals?\b|\breal (?:zeros?|roots?|solutions?)\b/i.test(text);
  const explicitComplex=/\bcomplex(?: numbers| zeros?| roots?| solutions?)\b/i.test(text);
  const zeroRequest=/^(?:(?:find|calculate|determine|give(?: me)?)\s+(?:all\s+)?(?:the\s+)?(?:real\s+|complex\s+)?(?:zeros?|roots?|x[ -]intercepts?)\s+(?:of|for)\s+|(?:zeros?|roots?)\s+of\s+)/i;
