    if(/[a-wz]/i.test(text.replace(/(?:\d(?:\.\d*)?|\.\d+)e[+-]?\d+/gi,'')))return null;
    const difference=rationalBinary('-',parseExpression(leftInput,v),parseExpression(rightInput,v));
    if(op==='=')return equationReply(difference,v,{onlyReal:onlyReal||/intercepts?/i.test(input),explicitComplex,zeros});
    return inequalityReply(difference,op,v);
  }catch(error){
    if(error instanceof RangeError)return {text:error.message,steps:['Check the denominator in the original expression.'],
      intent:'clarify',links:[references.equations]};
    if(error instanceof UnresolvedPolynomial)return {
      text:'I couldn’t finish factoring this expression exactly. Check whether your problem allows estimated zeros or provides a factor.',
      steps:['Put the polynomial on one side and list the possible rational roots. If none works, an exact answer may need another method.'],
      intent:'clarify',links:[references.zeros]};
    if(error instanceof SyntaxError)return null;
    throw error;
  }
}

