      const cube=!root;
      result=by(signed(cube?'cbrt('+variable+')':variable+'²',b),m);
      steps=['Swap the roles of input and output in '+display(body)+'.',
        cube?'Take the cube root of the new input to undo the cube.':'Square the new input to undo the square root.',
        'Subtract '+number(b)+' and divide by '+number(m)+' to undo the inside linear rule.'];
      if(!cube)restriction='The inverse’s inputs satisfy '+variable+' ≥ 0, because the original square root outputs nonnegative values.';
    }else if(/^(?:e\s*\^\s*\(?[xy]\)?|exp\(\s*[xy]\s*\))$/i.test(ungroup(body))&&body.includes(variable)){
      result='ln('+variable+')';
      steps=['The natural logarithm undoes an exponential with base e.'];
      restriction='The inverse’s inputs satisfy '+variable+' > 0.';
    }else if(root?.[0]==='ln'&&root[1]===variable){
      result='e^'+variable;
      steps=['Raising e to the output of a natural logarithm recovers its positive input.'];
    }
  }
  if(result)return {text:'Find the rule that reverses the original input and output.',steps:[...steps,...(restriction?[restriction]:[])],
    answer:label+' = '+result,links:[inverses],intent:'worked',
    reason:'The inverse reverses a one-to-one rule. Apply the inverse operations in reverse order.'};
  if(coefficients)return {text:coefficients[2]?'A quadratic repeats output values on opposite sides of its vertex.':'A constant function gives the same output for all real inputs.',
    steps:[coefficients[2]?'Restrict the original domain to one side of the vertex if your problem calls for a quadratic inverse.':'One output would correspond to many possible inverse outputs.'],
    answer:'No inverse function on the entire real domain.',links:[inverses],intent:'worked'};
  return null;
}

function affineInterval(bound,slope,strict){
  if(slope>0)return (strict?'(':'[')+bound+', ∞)';
  return '(−∞, '+bound+(strict?')':']');
}
function properties(definition,mathInput){
  const {body,variable}=definition;
  const polynomialValues=polynomial(mathInput,body,variable);
  if(polynomialValues){
    const [c,b,a]=polynomialValues;
    if(!a)return {domain:real,range:b?real:'{'+number(c)+'}',reason:b?'A nonconstant line covers every real input and every real output.':'A constant rule accepts every real input but gives only one output.'};
    const vertex=ratio(-b,2*a,mathInput),extreme=ratio(4*a*c-b*b,4*a,mathInput);
    return {domain:real,range:a>0?'['+extreme+', ∞)':'(−∞, '+extreme+']',
      reason:'The vertex is ('+vertex+', '+extreme+'). It gives the '+(a>0?'minimum':'maximum')+' output.'};
  }
  const call=simpleCall(body);
  if(call){
    const inner=polynomial(mathInput,call[1],variable);
    if(inner&&!inner[2]&&inner[1]){
      const [c,b]=inner;
      const bound=ratio(-c,b,mathInput);
      if(call[0]==='sqrt'||call[0]==='ln'||call[0]==='log'){
        const strict=call[0]!=='sqrt';
        return {domain:affineInterval(bound,b,strict),range:strict?real:'[0, ∞)',
          reason:'Require '+display(call[1])+(strict?' > 0 inside the logarithm.':' ≥ 0 inside the square root.')};
      }
      if(call[0]==='exp')return {domain:real,range:'(0, ∞)',reason:'An exponential output is positive and can be arbitrarily close to zero.'};
      if(call[0]==='cbrt')return {domain:real,range:real,reason:'A cube root accepts all real inputs and reaches every real output.'};
      if(call[0]==='abs')return {domain:real,range:'[0, ∞)',reason:'Absolute value is never negative and reaches zero when the inside expression is zero.'};
    }
  }
  const fraction=simpleQuotient(body);
  if(fraction){
    const numerator=polynomial(mathInput,fraction[0],variable),denominator=polynomial(mathInput,fraction[1],variable);
    if(numerator&&denominator&&!denominator[2]&&denominator[1]){
      const [d,e]=denominator;
      const excluded=ratio(-d,e,mathInput);
      const result={domain:'(−∞, '+excluded+') ∪ ('+excluded+', ∞)',reason:'The original denominator is zero at '+variable+' = '+excluded+'.'};
      if(!numerator[2]){
        const [c,b]=numerator;
        const endpoint=ratio(b,e,mathInput);
        result.range=c*e===b*d?'{'+endpoint+'}':'(−∞, '+endpoint+') ∪ ('+endpoint+', ∞)';
      }
      return result;
    }
    if(denominator?.every(value=>value===0))return {domain:'∅',range:'∅',reason:'The denominator is zero at every input.'};
  }
  const cubed=cubeInside(body);
  const inner=cubed&&polynomial(mathInput,cubed,variable);
  if(inner&&!inner[2]&&inner[1])return {domain:real,range:real,reason:'A cubed nonconstant linear expression can take every real value.'};
  return {reason:domainNote(body,variable,mathInput)};
}

function propertyReply(definition,query,mathInput){
  const asksDomain=/\bdomain\b/i.test(query),asksRange=/\brange\b/i.test(query);
  const report=properties(definition,mathInput);
  const items=[];
  if(asksDomain&&report.domain)items.push('Domain '+report.domain);
  if(asksRange&&report.range)items.push('Range '+report.range);
  const partial=asksDomain&&!report.domain||asksRange&&!report.range;
  return {text:partial?'I can show a starting condition for this rule. An exact '+(asksRange?'range':'domain')+' takes more analysis here.':
    'The domain lists allowed inputs. The range lists possible outputs.',
    steps:[report.reason],answer:items.length?items.join(' · '):undefined,links:[domain],intent:partial?'clarify':'worked'};
}

function linearProperties(definition,query,mathInput){
  const [b,m,a]=polynomial(mathInput,definition.body,definition.variable)??[];
  if(b===undefined||a!==0)return null;
  const asksSlope=/\bslope\b/i.test(query);
  const xSpecific=/\bx[- ]?intercept/.test(query.toLowerCase()),ySpecific=/\by[- ]?intercept/.test(query.toLowerCase());
  const genericIntercept=/\bintercepts?\b/i.test(query)&&!xSpecific&&!ySpecific;
  const xIntercept=m?'x-intercept ('+ratio(-b,m,mathInput)+', 0)':b?'No x-intercept':'Every point on the x-axis is an intercept';
  const answer=[...(asksSlope?['Slope '+number(m)]:[]),...(xSpecific||genericIntercept?[xIntercept]:[]),
    ...(ySpecific||genericIntercept?['y-intercept (0, '+number(b)+')']:[])].join(' · ');
  return {text:'Read the coefficients after writing the line in slope-intercept form.',formula:'y = mx + b',
    steps:[simplify(mathInput,definition.body)+' is the rule in slope-intercept form.',
      'The coefficient '+number(m)+' is the slope. Setting the input to 0 gives the y-intercept '+number(b)+'.',
      ...(xSpecific||genericIntercept?['For an x-intercept, set the output equal to 0. '+xIntercept+'.']:[])],
    answer,links:[lines],intent:'worked',reason:'The slope is the change in output for a one-unit increase in input. The y-intercept is the value at zero input.'};
}

function pointLineReply(input,mathInput){
  const query=/^(?:(?:can|could|would) you )?(?:please )?(?:find|what (?:is|are))\s+(?:the )?(slope|equation)(?:\s+and\s+(slope|equation))?\s+of\s+(?:the |a )?line\s+(?:through|passing through)\s*/i.exec(input);
  if(!query)return null;
  const point=/\(\s*([+-]?(?:\d+(?:\.\d+)?|\.\d+))\s*,\s*([+-]?(?:\d+(?:\.\d+)?|\.\d+))\s*\)/g;
  const tail=input.slice(query[0].length);
  const matches=[...tail.matchAll(point)];
  if(matches.length!==2||!/^(?:,|and)?$/i.test(tail.replace(point,'').trim()))return null;
  const [[,x1,y1],[,x2,y2]]=matches.map(match=>match.map(Number));
  if(![x1,y1,x2,y2].every(Number.isFinite)||x1===x2&&y1===y2)return null;
  const rise=y2-y1,run=x2-x1;
  if(!run)return {text:'The points have the same x-value, so their line is vertical.',
    steps:['The run is 0, and the rise is '+number(rise)+'. A slope would require dividing by zero.'],
    answer:'x = '+number(x1)+' · Slope undefined',links:[lines],intent:'worked'};
  const slope=ratio(rise,run,mathInput);
  const intercept=ratio(y1*run-rise*x1,run,mathInput);
  const xTerm=slope==='1'?'x':slope==='−1'?'−x':(slope.includes('/')?'('+slope+')':slope)+'x';
  const equation='y = '+(rise===0?intercept:xTerm+(intercept==='0'?'':intercept.startsWith('−')?' − '+intercept.slice(1):' + '+intercept));
  const asksEquation=/\bequation\b/i.test(query[0]),asksSlope=/\bslope\b/i.test(query[0]);
  return {text:'Use the change in y divided by the change in x.',formula:'m = (y₂ − y₁)/(x₂ − x₁)',
    steps:['Rise = '+number(y2)+' − ('+number(y1)+') = '+number(rise)+'. Run = '+number(x2)+' − ('+number(x1)+') = '+number(run)+'.',
      'The slope is '+slope+'. Substitute the first point into y = mx + b to get b = '+intercept+'.'],
    answer:[...(asksSlope?['Slope '+slope]:[]),...(asksEquation?[equation]:[])].join(' · '),links:[lines],intent:'worked'};
}
function transformReply(definition,mathInput){
  const [c,b,a]=polynomial(mathInput,definition.body,definition.variable)??[];
  if(!a)return null;
  const shift=-b/(2*a),offset=c+b*shift+a*shift**2;
  const steps=[];
  if(a<0)steps.push('Reflect across the x-axis because the leading coefficient is negative.');
  if(Math.abs(a)!==1)steps.push('Vertically '+(Math.abs(a)>1?'stretch':'compress')+' by a factor of '+number(Math.abs(a))+'.');
  if(shift)steps.push('Move '+number(Math.abs(shift))+' units '+(shift>0?'right':'left')+'.');
  if(offset)steps.push('Move '+number(Math.abs(offset))+' units '+(offset>0?'up':'down')+'.');
  return {text:'Compare the quadratic with the parent function y = x².',formula:'y = a(x − h)² + k',
    steps:steps.length?steps:['The rule is already the parent function.'],
    answer:'Vertex ('+number(shift)+', '+number(offset)+')',links:[transformations],intent:'worked'};
}

export function solveAlgebraFunctions(raw,mathInput,priorDefinitions=[]){
  if(typeof mathInput!=='function')return null;
  const input=String(raw??'').trim().replace(/[?!]+$|(?<=[xy²³)\]])\.$/i,'').trim()
    .replaceAll('−','-').replaceAll('×','*').replaceAll('÷','/').replace(/[‘’]/g,"'");
  if(!input||input.length>500)return null;
  const line=pointLineReply(input,mathInput);
  if(line)return line;
  const {definitions,request}=extract(input);
  if(!definitions.length&&/[fghpq]\s*\(\s*[xy]\s*\)\s*=/i.test(input))return null;
  const context=new Map((Array.isArray(priorDefinitions)?priorDefinitions:[]).filter(row=>row&&safeExpression(row.body)&&/^[fghpqy]$/.test(row.name)&&/^[xy]$/.test(row.variable))
    .map(row=>[row.name,row]));
  for(const row of definitions)context.set(row.name,row);
  if(!context.size)return null;
  const available=[...context.values()];
  const query=request.trim().replace(/^[,;: ]+|[,;: .]+$/g,'').replace(/\s+(?:if|when|given|where|for|with)$/i,'').trim();
  const get=name=>name&&context.get(name.toLowerCase());
  const withContext=reply=>reply?{...reply,functionDefinitions:available}:null;
  const chain=/\b([fghpq])\s*\(\s*([fghpq])\s*\(\s*(.+)\s*\)\s*\)\s*$/i.exec(query)
    ??/\b([fghpq])\s+of\s+([fghpq])\s+of\s+(.+)$/i.exec(query)
    ??/\b([fghpq])\s+of\s+([fghpq])\s*\(\s*(.+)\s*\)\s*$/i.exec(query)
    ??/\(?\s*\b([fghpq])\s*(?:∘|○|\bo\b)\s*([fghpq])\s*\)?(?:\s*\((.+)\))?\s*$/i.exec(query);
  if(chain&&get(chain[1])&&get(chain[2]))return withContext(compose(get(chain[1]),get(chain[2]),chain[3]?.trim()??get(chain[2]).variable,mathInput));
  const operation=findFunctionOperation(query);
  if(operation&&get(operation[0])&&get(operation[2])){
    return withContext(combineFunctions(get(operation[0]),operation[1],get(operation[2]),operation[3],mathInput));
  }
  const inverse=/\b([fghpq])\s*(?:\^\s*\(?-1\)?|⁻¹)\s*\(\s*[xy]\s*\)|\binverse\b(?:\s+of)?(?:\s+([fghpq])\b)?/i.exec(query);
  const target=query.match(/\b([fghpq])\s*(?:\(\s*[xy]\s*\)|\b)/i)?.[1];
  const definition=get(target)??(definitions.length===1?definitions[0]:available.length===1?available[0]:null);
  const asksAboutContext=definitions.length||get(target)||/^(?:(?:what is|what's|find|show|compute|determine)\s+)?(?:(?:the|its)\s+)?(?:inverse|domain(?: and range)?|range|slope|intercepts?|transformations?)(?:\s+of\s+(?:it|this function|the function))?$/i.test(query);
  if(inverse&&asksAboutContext){
    const selected=get(inverse[1]??inverse[2])??definition;
    if(selected)return withContext(inverseReply(selected,mathInput));
  }
  if(definition&&asksAboutContext&&/\b(?:domain|range)\b/i.test(query))return withContext(propertyReply(definition,query,mathInput));
  if(definition&&asksAboutContext&&/\b(?:slope|y.intercept|intercepts?)\b/i.test(query))return withContext(linearProperties(definition,query,mathInput));
  if(definition&&asksAboutContext&&/\b(?:transformations?|shifts?|vertex form)\b/i.test(query))return withContext(transformReply(definition,mathInput));
  const direct=/\b([fghpq])\s*\(\s*(.+)\s*\)\s*(?:if|when|given|and)?\s*$/i.exec(query)??/\b([fghpq])\s+of\s+(.+)$/i.exec(query);
  if(direct&&get(direct[1]))return withContext(directFunction(get(direct[1]),direct[2].trim(),mathInput,available));
  if(definitions.length&&(!query||/^(?:given|if|when|for|and|let)$/i.test(query))){
    return withContext({text:'I have the function '+(definitions.length===1?'rule':'rules')+'. What would you like to find?',
      actions:definitions.map(row=>['Show '+row.name+'('+row.variable+')','Find '+row.name+'('+row.variable+')']),
      links:[notation],intent:'clarify'});
  }
  if(definition&&asksAboutContext&&command.test(query)&&/\b(?:function|rule)\b/i.test(query))return withContext(directFunction(definition,definition.variable,mathInput,available));
  return null;
}

