 if(ch){const n=Number(ch[1]),title=algebraChapters[n-1];const rows=notes.filter(row=>row[0]===n);return {title,text:title,steps:rows.map(row=>row[2]+'. '+row[3]),links:[section(n,title)],actions:rows.map(row=>[row[2],`Explain algebra topic ${notes.indexOf(row)+1}`]),intent:'concept'};}
