const book = 'https://openstax.org/books/college-algebra-2e/pages/';
const section = (title, slug) => ['OpenStax College Algebra 2e · ' + title, book + slug];
const equations = section('Exponential and logarithmic equations', '6-6-exponential-and-logarithmic-equations');
const logRules = section('Logarithmic properties', '6-5-logarithmic-properties');
const arithmetic = section('Arithmetic sequences', '9-2-arithmetic-sequences');
const geometric = section('Geometric sequences', '9-3-geometric-sequences');
const series = section('Series and their notations', '9-4-series-and-their-notations');
const exponentialFunctions = section('Exponential functions and compound interest', '6-1-exponential-functions');
const exponentialModels = section('Exponential growth and decay models', '6-7-exponential-and-logarithmic-models');

const exponentialExample = 'Solve 3^(2x−1) = 20';
const logExample = 'Solve log(x) + log(x−3) = 1';
const sequenceExample = 'Find the 12th term of the arithmetic sequence 4, 7, 10, …';
const seriesExample = 'Find the infinite sum 12 + 6 + 3 + …';
const interestExample = 'What is the balance after 4 years if $1500 is invested at 5% interest compounded monthly?';
const growthExample = 'A town starts with 800 people and grows by 3% per year. How many people after 5 years?';
const superscript = '⁰¹²³⁴⁵⁶⁷⁸⁹';
const subscript = '₀₁₂₃₄₅₆₇₈₉';
const digits = String.raw`(?:\d+(?:\.\d*)?|\.\d+)`;
const number = String.raw`(?:${digits}(?:e[+-]?\d+)?)(?:/${digits})?`;
const scalarPattern = new RegExp('^[+-]?' + number + '$', 'i');
const affinePattern = /^[0-9xytn.e()+*/^\s-]+$/i;
const ordinalWords = new Map('first second third fourth fifth sixth seventh eighth ninth tenth'.split(' ').map((word, i) => [word, i + 1]));
const countWords = new Map('one two three four five six seven eight nine ten eleven twelve'.split(' ').map((word, i) => [word, i + 1]));
const countPattern = '\\d{1,5}|' + [...countWords.keys()].join('|');
const nice = text => String(text).replace(/(?<![Ee])-/g, '−');
const decimal = value => nice(String(Number(value.toPrecision(12))));
const close = (a, b) => Math.abs(a - b) <= 2e-12 * Math.max(Math.abs(a), Math.abs(b), Number.MIN_VALUE);

function normalize(input) {
  return String(input ?? '').trim().replace(/[?!]+$/, '').replace(/(?<!\d)\.$/, '')
    .replace(/[−–]/g, '-').replace(/×|·/g, '*').replace(/÷/g, '/')
    .replace(/[⁰¹²³⁴⁵⁶⁷⁸⁹⁻⁺]+/g, value => '^(' + [...value].map(c => c === '⁻' ? '-' : c === '⁺' ? '+' : superscript.indexOf(c)).join('') + ')')
    .replace(/[₀₁₂₃₄₅₆₇₈₉]+/g, value => '_' + [...value].map(c => subscript.indexOf(c)).join(''))
    .toLowerCase();
}

function worked(text, formula, steps, answer, link, examplePrompt, reason, alternate) {
  return {text, formula, steps, answer, links: [link], intent: 'worked', examplePrompt, reason, alternate};
}

function scalar(text, mathInput) {
  const literal = text.trim();
  if (literal === 'e') return Math.E;
  if (!scalarPattern.test(literal)) return null;
  const value = mathInput(literal, 'graph').valueAt(0);
  return Number.isFinite(value) ? value : null;
}

function exactArithmetic(expression, mathInput) {
  const evaluated = mathInput(expression);
  const exact = evaluated.formatAnswer?.('fraction');
  if (exact && !exact.startsWith('≈') && exact.length < 24) return nice(exact.replace(/\/1$/, ''));
  return '≈ ' + nice(evaluated.answer);
}

function variableOf(text) {
  const names = [...new Set(text.match(/[xytn]/g) ?? [])];
  return names.length === 1 ? names[0] : null;
}

function affine(text, variable, mathInput) {
  if (!text || !affinePattern.test(text)) return null;
  const polynomial = mathInput(text.replaceAll(variable, 'x'), 'simplify').answer;
  if (/[²³⁴⁵⁶⁷⁸⁹^]/.test(polynomial)) return null;
  const coefficients = polynomial.replace(/\s+/g, '').replace(/−/g, '-').match(/^([+-]?(?:\d+(?:\.\d+)?(?:e[+-]?\d+)?)?)x([+-].+)?$/);
  const interceptText = coefficients ? coefficients[2] ?? '0' : polynomial.replace(/−/g, '-');
  const slopeText = coefficients ? ['-', '+', ''].includes(coefficients[1]) ? coefficients[1] + '1' : coefficients[1] : '0';
  const slope = Number(slopeText);
  const intercept = Number(interceptText);
  return Number.isFinite(slope) && Number.isFinite(intercept) ? {slope, intercept, slopeText, interceptText} : null;
}

function matchingParen(input, start) {
  let depth = 0;
  for (let i = start; i < input.length; i++) {
    if (input[i] === '(') depth++;
    if (input[i] === ')' && --depth === 0) return i;
  }
  return -1;
}

function bareEquation(input) {
  const clean = input.replace(/^(?:(?:can|could|would) you |how (?:do|can|should) i )?(?:please )?(?:solve|find the solution (?:for|of|to)|find [xytn] (?:if|when|in))\s+(?:the (?:exponential |logarithmic )?equation\s*)?(?:for [xytn]\s*[:,]?\s*)?/i, '')
    .replace(/\s+for [xytn]$/, '').replace(/\s+(?:show|explain) (?:your |the )?(?:work|steps)$/, '');
  const [left, right, extra] = clean.split('=').map(side => side.trim());
  const wrapLog = side => side.replace(/((?:ln|log(?:_(?:\d+(?:\.\d+)?|e))?))\s+([xytn]|\d+(?:\.\d+)?)(?=\s*(?:[+-]|$))/g, '$1($2)');
  return left && right && extra === undefined ? [wrapLog(left), wrapLog(right)] : null;
}

function power(text, mathInput) {
  const head = new RegExp('^([+-]?(?:' + number + '\\*|' + number + '(?=e\\^))?)(\\(' + number + '\\)|' + digits + '|e)\\^', 'i').exec(text);
  if (!head) return null;
  const [, factorText, baseText] = head;
  const start = head[0].length;
  const end = text[start] === '(' ? matchingParen(text, start) : -1;
  const simple = end < 0 && /^([xytn]|[+-]?\d+)(?=$|[+-])/.exec(text.slice(start));
  if (end < 0 && !simple) return null;
  const exponent = end >= 0 ? text.slice(start + 1, end) : simple[0];
  const remainder = text.slice(end >= 0 ? end + 1 : start + exponent.length);
  if (remainder && !/^[+-]/.test(remainder)) return null;
  const coefficientText = factorText === '-' ? '-1' : factorText === '+' || !factorText ? '1' : factorText.replace(/\*$/, '');
  const coefficient = scalar(coefficientText, mathInput);
  const base = scalar(baseText.replace(/^\(|\)$/g, ''), mathInput);
  const offset = remainder ? scalar(remainder, mathInput) : 0;
  if (coefficient === null || base === null || base <= 0 || base === 1 || offset === null) return null;
  return {coefficient, coefficientText, base, baseText, exponent, offset, offsetText: remainder || '0'};
}

function exponential(sides, mathInput) {
  const [leftText, rightText] = sides.map(side => side.replace(/\s+/g, ''));
  const variable = variableOf(leftText + rightText);
  if (!variable) return null;
  const left = power(leftText, mathInput);
  const right = power(rightText, mathInput);
  if (left && right && left.offset === right.offset && left.coefficient * right.coefficient > 0) {
    const first = affine(left.exponent, variable, mathInput);
    const second = affine(right.exponent, variable, mathInput);
    if (!first || !second || !first.slope && !second.slope) return null;
    const ratio = Math.log(right.base) / Math.log(left.base);
    const powerRatio = Math.round(ratio);
    const inverseRatio = Math.round(1 / ratio);
    const sharedBase = left.coefficient === right.coefficient
      && (left.base ** powerRatio === right.base || right.base ** inverseRatio === left.base);
    const l = sharedBase ? left.base ** powerRatio === right.base ? 1 : inverseRatio : Math.log(left.base);
    const r = sharedBase ? left.base ** powerRatio === right.base ? powerRatio : 1 : Math.log(right.base);
    const slope = l * first.slope - r * second.slope;
    const constant = r * second.intercept - l * first.intercept + (sharedBase ? 0 : Math.log(Math.abs(right.coefficient)) - Math.log(Math.abs(left.coefficient)));
    const zeroSlope = sharedBase ? slope === 0 : close(l * first.slope, r * second.slope);
    const denominator = '(' + l + '*(' + first.slopeText + ')-' + r + '*(' + second.slopeText + '))';
    const numerator = '(' + r + '*(' + second.interceptText + ')-' + l + '*(' + first.interceptText + '))';
    const answer = zeroSlope
      ? close(constant, 0) ? 'All real numbers' : 'No real solution'
      : variable + (sharedBase ? ' = ' + exactArithmetic(numerator + '/' + denominator, mathInput) : constant === 0 ? ' = 0' : ' ≈ ' + decimal(constant / slope));
    return worked('Turn the exponent equation into a linear equation.',
      sharedBase ? 'b^A = b^B ⇒ A = B' : 'ln(b^A) = A·ln(b)',
      [sharedBase ? 'Remove any matching added constants and divide out the matching factors. Rewrite both powers with the same base, then set their exponents equal.' : 'Remove any matching added constants. Divide out the left coefficient so both sides are positive, then take ln and apply its power rule.',
        sharedBase ? decimal(l) + '·(' + nice(left.exponent) + ') = ' + decimal(r) + '·(' + nice(right.exponent) + ').'
          : 'Taking logs gives ' + decimal(l) + '·(' + nice(left.exponent) + ') = ' + decimal(r) + '·(' + nice(right.exponent) + ') + ln(' + decimal(right.coefficient / left.coefficient) + '), with rounded log values shown.',
        'Collect the terms in ' + variable + ' on one side of the linear equation.',
        zeroSlope ? 'The variable terms cancel. Check whether the constant terms agree.' : 'Divide both sides by the remaining coefficient of ' + variable + '.'],
      answer.replace(' = ≈ ', ' ≈ '), equations, exponentialExample,
      sharedBase ? 'Each exponent produces a distinct output when the base is positive and different from 1.' : 'The power rule brings the variable out of the exponent.',
      'Graph the two sides and compare their intersections with the solution.');
  }
  const model = left ?? right;
  if (!model || !model.coefficient) return null;
  const otherText = left ? rightText : leftText;
  const other = scalar(otherText, mathInput);
  const linear = affine(model.exponent, variable, mathInput);
  if (other === null || !linear?.slope) return null;
  const isolated = (other - model.offset) / model.coefficient;
  const isolate = 'Isolate the power: ' + nice(model.baseText) + '^(' + nice(model.exponent) + ') = ' + decimal(isolated) + '.';
  if (isolated <= 0) return worked('A positive base raised to a real power always gives a positive number.',
    'b^x > 0 for b > 0', [isolate, 'The isolated power is zero or negative.'], 'No real solution', equations, exponentialExample);
  if (!Number.isFinite(isolated)) return null;
  const exponent = Math.log(isolated) / Math.log(model.base);
  const integerExponent = Math.round(exponent);
  const exactValue = close(model.base ** integerExponent, isolated) && Math.abs(integerExponent) <= 100 && model.baseText !== 'e' && otherText !== 'e'
    && mathInput('(' + otherText + '-(' + model.offsetText + '))/(' + model.coefficientText + ')').formatAnswer('fraction')
      === mathInput('(' + model.baseText + ')^(' + integerExponent + ')').formatAnswer('fraction');
  const exactExponent = Boolean(exactValue || isolated === 1 || model.base ** integerExponent === isolated && Number.isSafeInteger(integerExponent));
  const expression = '(' + integerExponent + '-(' + linear.interceptText + '))/(' + linear.slopeText + ')';
  const answer = exactExponent ? variable + ' = ' + exactArithmetic(expression, mathInput)
    : variable + ' ≈ ' + decimal((exponent - linear.intercept) / linear.slope);
  const exponentStep = exactExponent
    ? 'Rewrite the right side as ' + nice(model.baseText) + '^(' + nice(integerExponent) + '). Set the two exponents equal.'
    : 'Take the natural log of both sides. The exponent equals ln(' + decimal(isolated) + ') ÷ ln(' + nice(model.baseText) + '), about ' + decimal(exponent) + '.';
  return worked('Isolate the power first, then bring down the exponent.', exactExponent ? 'b^A = b^B ⇒ A = B' : 'log_b(A) = ln(A) ÷ ln(b)',
    [isolate, exponentStep, 'Solve the resulting linear equation for ' + variable + '.'],
    answer.replace(' = ≈ ', ' ≈ '), equations, exponentialExample,
    'Logarithms undo exponentiation. Dividing by ln of the base leaves the original exponent.',
    'Graph each side as a function and read the ' + variable + '-coordinate where they meet.');
}

function readLog(text, start = 0) {
  const token = /^(ln|log(?:_([0-9][0-9.]*|e))?)\(/.exec(text.slice(start));
  if (!token) return null;
  const open = start + token[0].length - 1;
  const end = matchingParen(text, open);
  if (end < 0 || end === open + 1) return null;
  return {baseText: token[1] === 'ln' ? 'e' : token[2] ?? '10', name: token[1], argument: text.slice(open + 1, end), end: end + 1};
}

function logSide(text, mathInput) {
  const terms = [];
  let constant = 0;
  let start = 0;
  while (start < text.length && terms.length < 5) {
    const sign = text[start] === '-' ? -1 : 1;
    if (/[+-]/.test(text[start])) start++;
    const coefficientText = new RegExp('^' + number + '(?:\\*)?(?=ln\\(|log(?:_[\\w.]+)?\\()', 'i').exec(text.slice(start));
    if (coefficientText) start += coefficientText[0].length;
    const entry = readLog(text, start);
    if (entry) {
      const coefficient = coefficientText ? scalar(coefficientText[0].replace(/\*$/, ''), mathInput) : 1;
      const base = scalar(entry.baseText, mathInput);
      if (!coefficient || base === null || base <= 0 || base === 1) return null;
      terms.push({...entry, base, coefficient: sign * coefficient});
      start = entry.end;
    } else {
      const literal = new RegExp('^' + number).exec(text.slice(start));
      if (!literal || coefficientText) return null;
      constant += sign * scalar(literal[0], mathInput);
      start += literal[0].length;
    }
    if (start < text.length && !/[+-]/.test(text[start])) return null;
  }
  return start === text.length ? {terms, constant} : null;
}

function logEquation(sides, mathInput) {
  const [left, right] = sides.map(side => logSide(side.replace(/\s+/g, ''), mathInput));
  if (!left || !right) return null;
  const terms = [...left.terms, ...right.terms.map(term => ({...term, coefficient: -term.coefficient}))];
  const variable = variableOf(terms.map(term => term.argument).join(''));
  if (!terms.length || !variable || !terms.every(term => affinePattern.test(term.argument))) return null;
  const evaluated = terms.map(term => {
    const argument = mathInput(term.argument.replaceAll(variable, 'x'), 'simplify').answer;
    // The positive-domain check uses the original argument, before any cancellation.
    const valueAt = mathInput(term.argument.replaceAll(variable, 'x'), 'graph').valueAt;
    return {...term, argument, valueAt};
  });
  const valid = root => {
    try {
      return evaluated.every(term => term.valueAt(root) > 0);
    } catch {
      return false;
    }
  };
  const restrictions = [...new Set(terms.map(term => nice(term.argument) + ' > 0'))].join(', ');
  const domainStep = 'Keep each original log argument positive: ' + restrictions + '.';
  const nonconstant = evaluated.filter(term => /\bx\b/.test(term.argument) || /x[²³⁴⁵⁶⁷⁸⁹^]/.test(term.argument) || /\dx/.test(term.argument));
  const constant = right.constant - left.constant;
  let solveLeft, solveRight, formula, transform, exactRight;
  if (nonconstant.length === 1) {
    const target = nonconstant[0];
    let adjusted = constant;
    for (const term of evaluated) {
      if (term === target) continue;
      const value = term.valueAt(0);
      if (value <= 0) return worked('The original equation contains a log of a nonpositive constant.',
        'log_b(A) requires A > 0', [domainStep], 'No real solution', equations, logExample);
      adjusted -= term.coefficient * Math.log(value) / Math.log(term.base);
    }
    const exponent = adjusted / target.coefficient;
    solveLeft = target.argument;
    solveRight = String(target.base ** exponent);
    if (evaluated.length === 1 && solveLeft === 'x' && /[.e]/.test(solveRight)) exactRight = target.baseText + '^(' + decimal(exponent) + ')';
    if (!Number.isFinite(Number(solveRight)) || Number(solveRight) <= 0) return null;
    formula = 'log_b(A) = c ⇒ A = b^c';
    transform = 'Isolate the logarithm. Its value is ' + decimal(exponent) + '. Rewrite it in exponential form.';
  } else {
    const base = terms[0].base;
    if (!terms.every(term => term.base === base && Number.isSafeInteger(term.coefficient) && Math.abs(term.coefficient) <= 4)) return null;
    const group = sign => evaluated.filter(term => Math.sign(term.coefficient) === sign).map(term =>
      '(' + term.argument + ')' + (Math.abs(term.coefficient) > 1 ? '^' + Math.abs(term.coefficient) : '')
    ).join('*') || '1';
    const target = base ** constant;
    if (!Number.isFinite(target) || target <= 0) return null;
    solveLeft = group(1);
    solveRight = target === 1 ? group(-1) : target + '*(' + group(-1) + ')';
    formula = 'log_b(A) − log_b(B) = log_b(A ÷ B)';
    transform = 'Combine same-base logs using the product, quotient, and power rules. Then undo the log by exponentiating and clear the denominator.';
  }
  const result = mathInput(solveLeft + '=' + solveRight, 'solve');
  const roots = result.roots ?? [];
  const accepted = roots.filter(valid);
  const rejected = roots.filter(root => !valid(root));
  const check = rejected.length ? 'Reject ' + rejected.map(decimal).join(' and ') + ' because an original log argument is zero or negative.'
    : accepted.length ? 'Check all original log arguments at the candidate. Each is positive.' : 'The transformed equation has no real candidate satisfying the log domain.';
  const exactResult = !rejected.length && !/[e.]/.test(solveRight) && result.formatAnswer?.('fraction').replaceAll(/\/1\b/g, '');
  const integerResult = accepted.length > 0 && accepted.every(Number.isSafeInteger) && !/[e.]/.test(solveRight);
  const answer = accepted.length ? exactRight ? variable + ' = ' + exactRight + ' ≈ ' + accepted.map(decimal).join(' or ')
    : exactResult && !exactResult.includes('≈') ? nice(exactResult.replaceAll('x', variable))
      : variable + (integerResult ? ' = ' : ' ≈ ') + accepted.map(decimal).join(' or ')
    : /^all real/i.test(result.answer) ? 'Every value satisfying ' + restrictions : 'No real solution';
  return worked('Check the domain before keeping any solution.', formula,
    [domainStep, transform, 'Solve ' + nice(solveLeft.replaceAll('x', variable)) + ' = ' + nice(solveRight.replaceAll('x', variable)) + '.', 
      /^all real/i.test(result.answer) ? 'The algebra simplifies to an identity, so retain the original domain restrictions.' : check],
    answer, equations, logExample, 'Algebra can introduce a candidate where an original logarithm is undefined. The original arguments decide which candidates count.',
    'Graph the original sides to check the roots, staying inside the log domain.');
}

function expandLog(input) {
  const match = /^(?:please )?expand\s+(?:the (?:logarithm|logarithmic expression)\s*[:,]?\s*)?(.+)$/.exec(input);
  if (!match) return null;
  const clean = match[1].replace(/\s+/g, '');
  const log = readLog(clean);
  const validBase = log && (log.baseText === 'e' || Number(log.baseText) > 0 && Number(log.baseText) !== 1);
