const periodsPerYear = {annually: 1, yearly: 1, 'semi-annually': 2, semiannually: 2, quarterly: 4, monthly: 12, weekly: 52, daily: 365};
const perYear = {year: 1, month: 12, week: 52, day: 365};
const timePattern = 'years?|months?|weeks?|days?|hours?|minutes?|seconds?';
const timeInput = new RegExp('(?:after|for|over|in)\\s+(' + digits + ')\\s+(' + timePattern + ')\\b');
const percentInput = new RegExp('([+-]?' + digits + ')\\s*(?:%|percent\\b)');
