    (Number.isSafeInteger(answer) ? '' : '≈ ') + decimal(answer) + outputUnit,
    exponentialModels, growthExample, 'A fixed percent acts on the current amount every interval, so the amount is multiplied repeatedly.',
    'If the elapsed time is a whole number of intervals, apply the multiplier one interval at a time.');
}

export function solveAlgebraModels(input, mathInput) {
