  ||/^(?:(?:can|could|would) you\s+|how (?:do|can|should) i\s+)?(?:please\s+)?(?:solve|find the solution to)\s+(?:(?:the|this|a)\s+)?system\s*(?=[:{\dxy+−-]|[?.!]*$)/i.test(input.trim());
 const raw=input.trim().replace(/[?.!]+$/,'').trim().replace(/[−–]/g,'-').replace(/[×·]/g,'*');
 if(explicit&&/\b(?:immune|nervous|circulatory|organ|ecological|cardiovascular|endocrine|buffer)\s+system\b/i.test(raw))return null;
 const cleaned=raw.replace(/^(?:(?:can|could|would) you\s+|how (?:do|can|should) i\s+)?(?:please\s+)?(?:solve|find the solution to)\s*/i,'')
  .replace(/^(?:(?:the|this|a)\s+)?(?:linear\s+)?system(?:\s+of\s+(?:linear\s+)?equations)?\s*:?\s*/i,'')
  .replace(/^[:{]\s*/,'').replace(/\s*}\s*$/,'').trim().replace(/[XY]/g,letter=>letter.toLowerCase());
 if(!explicit&&((cleaned.match(/=/g)?.length??0)!==2||!/[xy]/.test(cleaned)))return null;
 const lines=cleaned.split(/\s*(?:;|\r?\n|,|\band\b)\s*/i).filter(Boolean);
 if(!explicit&&(!/^[\dxy\s=+*/().,;\-]+$/i.test(cleaned.replace(/\band\b/gi,''))||lines.length!==2))return null;
 const links=[source];
 const examples=[['Try a system','Solve the system 2x + y = 11; x − y = 1']];
 const clarify=()=>({text:'Enter two linear equations in x and y, separated by a semicolon or a new line. For example, 2x + y = 11; x − y = 1.',links,actions:examples,intent:'clarify'});
 if(lines.length!==2)return explicit?clarify():null;
 let first,second;
 try{first=eq(lines[0]);second=eq(lines[1]);}
 catch{return explicit?clarify():null;}
 const [a,b,c]=first,[d,e,f]=second;
 const formula=rowText(first)+'  |  '+rowText(second);
 const main={formula,links,intent:'worked',practicePrompt:'Solve the system x + 3y = 10; 2x − y = 6'};
 const eliminated=diff(scale(first,e),scale(second,b));
 if(zero(eliminated[0])){
  const contradictory=(!zero(c)&&zero(a)&&zero(b))||(!zero(f)&&zero(d)&&zero(e))||!zero(eliminated[2])||!zero(sub(mul(d,c),mul(a,f)));
