 }
 const x=div(eliminated[2],eliminated[0]);
 const useFirst=!zero(b);
 const [p,q,r]=useFirst?first:second;
 const y=div(sub(r,mul(p,x)),q);
 const steps=[
  zero(b)||zero(e)
   ?'One equation contains only x. Divide both sides by its x coefficient to get x = '+display(x)+'.'
   :'Eliminate y. Multiply equation 1 by '+display(e)+' and subtract equation 2 multiplied by '+display(b)+'. This gives '+rowText(eliminated)+', so x = '+display(x)+'.',
  'Substitute x = '+display(x)+' into equation '+(useFirst?'1':'2')+'. Subtract the x term to get '+rowText([rat(0n),q,sub(r,mul(p,x))])+', then divide to get y = '+display(y)+'.',
  'Check both equations. The rearranged first equation gives '+display(evaluate(first,x,y))+' = '+display(c)+' and the second gives '+display(evaluate(second,x,y))+' = '+display(f)+'.'
 ];
 return {...main,text:'Solve both equations at once by finding a single pair (x, y) that works in each.',steps,answer:'(x, y) = ('+display(x)+', '+display(y)+')',
  reason:'Elimination makes the y coefficients match. Subtracting the equations then removes y, leaving one equation in x.',
  alternate:'Use substitution instead. Rearrange equation '+(useFirst?'1':'2')+' to get y = ('+display(r)+' − ('+display(p)+')x)/('+display(q)+'). Substitute that expression for y into the other equation, then solve for x.'};
}

