const root='https://openstax.org/books/college-algebra-2e/pages/';
const source=(name,slug)=>['OpenStax College Algebra 2e · '+name,root+slug];
const factoring=source('Factoring polynomials','1-5-factoring-polynomials');
const inequalities=source('Linear inequalities','2-7-linear-inequalities-and-absolute-value-inequalities');
const functions=source('Functions and function notation','3-1-functions-and-function-notation');
const pretty=value=>String(Number(value.toPrecision(12))).replaceAll('-','−');
const display=text=>String(text).replace(/(?<![Ee])-+/g,'−');
const gcd=(a,b)=>{
  for(a=Math.abs(a),b=Math.abs(b);b;)[a,b]=[b,a%b];
