};
const canonicalTerm=/([+\-]?)(?:(\d+(?:\.\d*)?|\.\d+)(e[+\-]?\d+)?)?([xy])?(²)?/gy;
const factoredRule='To split ax² + bx + c, look for two numbers whose sum is b and whose product is a·c.';

function parsePolynomial(mathInput,input){
  if(!input.trim()||input.includes('='))throw Error('Enter a polynomial expression on each side.');
  const expression=mathInput(input,'simplify').answer;
  const text=expression.replace(/[\s]/g,'').replaceAll('−','-');
  canonicalTerm.lastIndex=0;
  const coefficients=[0,0,0];
  let variable=null,at=0;
  while(at<text.length){
    const term=canonicalTerm.exec(text);
    if(!term?.[0]||term.index!==at||!term[2]&&!term[4])throw Error('Use terms in one variable, x or y.');
    const [,sign,mantissa,exponent,sym,squared]=term;
    if(sym&&variable&&variable!==sym)throw Error('Use a single variable.');
    if(sym)variable=sym;
    coefficients[sym?squared?2:1:0]+=Number((mantissa??'1')+(exponent??''))*(sign==='-'?-1:1);
    at=canonicalTerm.lastIndex;
  }
  return {coefficients,variable,expression};
}

function fraction(n,d){
  const divisor=gcd(n,d);
  const sign=d<0?-1:1;
  return [sign*n/divisor,sign*d/divisor];
}
function binomial(variable,n,d){
  if(!n)return (d===1?'':pretty(d))+variable;
  return '('+(d===1?'':pretty(d))+variable+(n>0?' − ':' + ')+pretty(Math.abs(n))+')';
}
function formatFactored(variable,common,roots){
  const prefix=common===1?'':common===-1?'−':pretty(common);
  const factors=roots.map(([n,d])=>binomial(variable,n,d));
  const product=factors[0]===factors[1]?factors[0]+'²':factors.join('');
  return prefix+product;
}
function guidance(text,nextPrompt,section,steps){
  return {text,steps,intent:'concept',links:[section],actions:[['Try an example',nextPrompt]],examplePrompt:nextPrompt};
}

function factorReply(input,mathInput){
  const request=input.match(/^(?:(?:can|could|would) you )?(?:please )?factor(?:ize|ise)?\s+(?:completely\s+)?(?:the (?:quadratic|trinomial|polynomial|expression)\s*)?(.+)$/i);
  if(!request||!/[\dx²^]/i.test(request[1]))return null;
  const polynomial=request[1].replace(/\s+using (?:the )?(?:ac method|grouping)$/i,'').trim()
    .replace(/\b([xy])\s+squared\b/gi,'$1²').replace(/\bplus\b/gi,'+').replace(/\bminus\b/gi,'−');
  // Natural language about chemical or biological factors belongs to the science tutor.
  if(!/^[\dxy()[\].+*/^²³×÷·−\s-]+$/i.test(polynomial))return null;
  const {coefficients:[c,b,a],variable,expression}=parsePolynomial(mathInput,polynomial);
  if(!a||!variable||![a,b,c].every(n=>Number.isSafeInteger(n)&&Math.abs(n)<=1e6))return {
    text:'For this factoring walkthrough, enter a quadratic in x or y with integer coefficients, such as 2x² + 7x + 3.',
    links:[factoring],intent:'clarify'
  };
  const common=gcd(gcd(a,b),c)*Math.sign(a);
  const A=a/common,B=b/common,C=c/common;
  const discriminant=B*B-4*A*C;
  const squareRoot=Math.sqrt(discriminant);
  const steps=common===1?[]:['Take out the common factor '+pretty(common)+' first.'];
  if(!Number.isInteger(squareRoot)){
    const primitive=mathInput('('+polynomial+')/'+pretty(common),'simplify').answer;
    return {
      text:discriminant<0?'The remaining quadratic has no real linear factors.':'The remaining quadratic has no factorization into integer linear factors.',
      formula:'Discriminant = b² − 4ac',steps:[...steps,'For the remaining quadratic, the discriminant is '+pretty(discriminant)+'.',
        discriminant<0?'A negative discriminant gives no real roots.':'The positive discriminant is not a perfect square, so the quadratic formula gives irrational roots.'],
      answer:common===1?undefined:pretty(common)+'('+primitive+')',links:[factoring],intent:'worked',
      reason:'Integer linear factors require rational roots. A non-square discriminant makes the roots irrational, or non-real when it is negative.',
      examplePrompt:'Factor 2x² + 7x + 3'
    };
  }
  const roots=[fraction(-B-squareRoot,2*A),fraction(-B+squareRoot,2*A)];
  const [m,n]=[(B-squareRoot)/2,(B+squareRoot)/2];
  const answer=formatFactored(variable,common,roots);
  if(C===0)steps.push('There is no constant term. Both terms have '+variable+' as a factor.');
  else{
    steps.push('Find two integers that multiply to '+pretty(A*C)+' and add to '+pretty(B)+'.');
    steps.push(pretty(m)+' and '+pretty(n)+' have that product and sum. Split the middle term using these coefficients, then factor the two groups.');
  }
  steps.push('Multiply the factors to check. The product is '+expression+'.');
  return {
    text:'Write the quadratic as a product of simpler expressions.',formula:C===0?undefined:factoredRule,
    steps,answer,links:[factoring],intent:'worked',examplePrompt:'Factor 6x² − 5x − 6',
    reason:C===0?'A missing constant term means every nonzero term contains the variable. Pull that shared factor out.':
      'The two middle terms created when you multiply the binomials must add to the original middle term. Splitting it helps you expose a shared factor.',
    alternate:'Find the roots with the quadratic formula. Each rational root n/d corresponds to a factor ('+variable+' − n/d), or a factor with integer coefficients after clearing the denominator.'
  };
}

const flipped={'<':'>','>':'<','≤':'≥','≥':'≤'};
const comparison={'<':(a,b)=>a<b,'>':(a,b)=>a>b,'≤':(a,b)=>a<=b,'≥':(a,b)=>a>=b};
function formatBound(n,d,mathInput){
  if(!Number.isSafeInteger(n)||!Number.isSafeInteger(d)){
    const ratio=mathInput('('+pretty(n)+')/('+pretty(d)+')');
    const exact=ratio.formatAnswer?.('fraction');
    return exact&&!exact.startsWith('≈')?display(exact.replace(/\/1$/,'')):pretty(n/d);
  }
  const [a,b]=fraction(n,d);
  return b===1?pretty(a):pretty(a)+'/'+pretty(b);
}
function interval(operator,bound){
  return operator==='<'?'(−∞, '+bound+')':operator==='≤'?'(−∞, '+bound+']':operator==='>'?'('+bound+', ∞)':'['+bound+', ∞)';
}
function inequalityReply(input,mathInput){
  const clean=input.replace(/^(?:(?:can|could|would) you |how (?:do|should|can) i )?(?:please )?(?:solve|find (?:the )?solution (?:to|of))\s+(?:the inequality\s*)?/i,'')
    .replace(/\s+(?:in interval notation|for [xy])$/i,'')
    .replace(/\bless than or equal to\b|<=/gi,'≤').replace(/\bgreater than or equal to\b|>=/gi,'≥')
    .replace(/\bless than\b/gi,'<').replace(/\bgreater than\b/gi,'>');
  if(!/^[\dxy()[\].+*/^²³×÷·−<>≤≥\s-]+$/i.test(clean)||!/[<>≤≥]/.test(clean))return null;
  const [leftText,operator,rightText,...extra]=clean.split(/([<>≤≥])/);
  if(!leftText?.trim()||!rightText?.trim()||extra.length)return null;
  const left=parsePolynomial(mathInput,leftText),right=parsePolynomial(mathInput,rightText);
  const originalVariables=[...new Set(clean.toLowerCase().match(/[xy]/g)??[])];
  const variable=left.variable??right.variable??(originalVariables.length===1?originalVariables[0]:null);
  if(!variable||left.variable&&right.variable&&left.variable!==right.variable)return null;
  if(left.coefficients[2]||right.coefficients[2])return null;
  const a=left.coefficients[1]-right.coefficients[1],b=right.coefficients[0]-left.coefficients[0];
  if(a===0){
    const trueForAll=comparison[operator](0,b);
    return {text:'The variable terms cancel. Test the comparison that remains.',steps:['Combine like terms to get 0 '+operator+' '+pretty(b)+'.'],
      answer:trueForAll?'All real numbers (−∞, ∞)':'No solution (∅)',links:[inequalities],intent:'worked',examplePrompt:'Solve −3x + 5 ≥ 11'};
  }
  const bound=formatBound(b,a,mathInput);
  const finalOperator=a<0?flipped[operator]:operator;
  const statement=variable+' '+finalOperator+' '+bound;
  const negative=a<0;
  const reason=negative?'Dividing by a negative reverses the order of any two numbers. Reverse the inequality symbol as well.':
    'We divided by a positive coefficient, so the original order of the two sides is preserved.';
  const steps=['Collect variable terms on the left and constants on the right: '+pretty(a)+variable+' '+operator+' '+pretty(b)+'.',
    'Divide both sides by '+pretty(a)+'. The boundary is '+pretty(b)+' ÷ ('+pretty(a)+') = '+bound+'. '+reason,
    statement+'. '+(operator==='<'||operator==='>'?'The endpoint is excluded.':'The endpoint is included.')];
  return {
    text:'Isolate '+variable+' and state the full set of values that satisfy the inequality.',
    steps,answer:statement+' · '+interval(finalOperator,bound),links:[inequalities],intent:'worked',reason,
    alternate:'Find the boundary by replacing the inequality with an equality. Test a value on each side of the boundary in the original inequality, then decide whether equality is allowed.',
    examplePrompt:'Solve −3x + 5 ≥ 11'
  };
}

function functionReply(input,mathInput){
  const definition=/([fghpq])\s*\(\s*([xy])\s*\)\s*=\s*(.+?)(?=\s*(?:[,;]|\b(?:and\s+)?(?:find|evaluate|calculate|what is|what's)\s+[fghpq]\s*\()|$)/i;
  const named=definition.exec(input);
  const direct=!named&&/^(?:(?:can|could|would) you )?(?:please )?(?:evaluate|calculate|find)\s+(.+?)\s+(?:at|when|for)\s+([xy])\s*=\s*(.+)$/i.exec(input);
  if(!named&&!direct)return null;
  let variable,body,argument,name;
  if(named){
    [,name,variable,body]=named;
    const remainder=input.slice(0,named.index)+' '+input.slice(named.index+named[0].length);
    const evaluation=new RegExp('\\b'+name+'\\s*\\((.+)\\)\\s*(?:if|when|given|and)?\\s*[,;:]?\\s*$','i').exec(remainder.trim());
    if(!evaluation)return null;
    argument=evaluation[1];
  }else{
    [,body,variable,argument]=direct;
  }
  body=body.trim();
  argument=argument.trim();
  if(!argument||!/[0-9π]|\b(?:pi|e)\b/i.test(argument)||/[=;,]/.test(body+argument))return null;
  const evaluation=mathInput(argument);
  const numeric=Number(evaluation.answer);
  if(!Number.isFinite(numeric))return null;
  const variableLower=variable.toLowerCase();
  const substituted=body.replace(/sqrt|cbrt|abs|log|ln|exp|sin|cos|tan|pi|[xy]/gi,
    part=>part.toLowerCase()===variableLower?'('+argument+')':part);
  const result=mathInput(substituted);
  if(typeof result.formatAnswer!=='function')return null;
  const exact=result.formatAnswer('fraction');
  const reported=/^[+-]?\d+\/[1-9]\d*$/.test(exact)&&!exact.endsWith('/1')?exact:result.answer;
  const notation=name?name.toLowerCase()+'('+display(argument)+')':null;
  const steps=['The input is '+variableLower+' = '+display(argument)+'. Replace every '+variableLower+' in the expression with ('+display(argument)+').',
    'After substitution: '+display(substituted)+'.',...result.steps];
  return {
    text:'Function notation tells you which input to substitute.',steps,answer:(notation?notation+' = ':'')+display(reported),
    links:[functions],intent:'worked',reason:'Parentheses keep a negative or grouped input together. For example, (−2)² is positive because the entire input is squared.',
    alternate:'After substitution, calculate each power or grouped expression first, then add or subtract the evaluated terms.',
    examplePrompt:'Given f(x) = 2x² + 3x − 1, find f(−2)'
  };
}

const followupActions=[
  ['Why this step?','Why does that step work?'],
  ['Next step','Next algebra step'],
  ['Try another method','Is there another way?'],
  ['Another example','Give me another algebra example']
];
const conceptWords=/^(?:what (?:is|are)|how (?:do|can) i|how (?:do|does)|explain|teach me|help me understand)\b/i;
function algebraConcept(input){
  if(!conceptWords.test(input))return null;
  if(/\b(?:factor(?:ing)?|factori[sz]e)\b.*\b(?:quadratics?|polynomials?|trinomials?)\b/i.test(input)){
    return guidance('Start with any factor shared by every term. Then look for the two numbers that let you split the middle term.',
      'Factor 2x² + 7x + 3',factoring,[factoredRule,'For a leading coefficient of 1, those two numbers go directly into the two binomials.']);
  }
  if(/\b(?:linear inequality|linear inequalities|flip.*inequality|reverse.*inequality|inequality.*sign)\b/i.test(input)){
    return guidance('Isolate the variable like you would in an equation. Multiplying or dividing both sides by a negative reverses which side is larger.',
      'Solve −3x + 5 ≥ 11',inequalities,['Since 2 < 5, multiplying each by −1 gives −2 > −5.']);
  }
  if(/\b(?:function notation|evaluate a function|evaluate functions)\b/i.test(input)){
    return guidance('In f(3), the 3 is the input. Replace every occurrence of the input variable in the function with 3, then simplify.',
      'Given f(x) = 2x² + 3x − 1, find f(−2)',functions,['Keep the input in parentheses if it is negative or a fraction.']);
  }
