}

export function createAlgebraTutor({mathInput}={}){
  let current=null,position=0,definitions=[];
  const reset=()=>{current=null;position=0;definitions=[];};
  const remember=reply=>{
    current=reply;
    position=0;
    definitions=reply.functionDefinitions??[];
    return {...reply,actions:reply.actions??followupActions};
  };
  function respond(raw,{clarify=true}={}){
    const input=String(raw??'').trim().replace(/[?!]+$/,'').trim();
    if(!input||input.length>500||/^(?:start over|new (?:problem|topic))$/i.test(input)){reset();return null;}
    let clarification;
    const solvers=[()=>solveAlgebraExtensions(input),()=>solveAlgebraFunctions(input,mathInput,definitions),
      ()=>solveAlgebraEquations(input,mathInput),()=>solveAlgebraModels(input,mathInput),()=>solveLinearSystem(input)];
    if(typeof mathInput==='function')solvers.push(()=>factorReply(input,mathInput),()=>inequalityReply(input,mathInput),()=>functionReply(input,mathInput));
    for(const solve of solvers){
      try{
        const result=solve();
        if(result&&result.intent!=='clarify')return remember(result);
        if(result&&!clarification)clarification=result;
      }catch { /* Let another solver handle overlapping syntax. */ }
    }
    if(clarification)return remember(clarification);
    if(current){
      if(/^(?:what(?:'s| is) the )?next(?: algebra)? step$/i.test(input)){
        const step=current.steps?.[position++];
        return {text:step??'That completes this walkthrough.',answer:step?undefined:current.answer,
          links:current.links,actions:followupActions,intent:'followup'};
      }
      if(/^(?:can you )?(?:show (?:me )?(?:the |your )?(?:work|solution|steps)|work it out)$/i.test(input)){
        return {...current,actions:followupActions};
      }
      if(/^(?:(?:can you )?(?:give|show) me )?(?:an |another )?(?:algebra )?example$/i.test(input)){
        return respond(current.examplePrompt??current.practicePrompt??'Factor 2x² + 7x + 3');
      }
      if(/^(?:is there )?(?:an? )?(?:another way|different way|alternative (?:way|method)|another method)$/i.test(input)&&current.alternate){
        return {text:current.alternate,links:current.links,actions:followupActions,intent:'followup'};
      }
      if(/^(?:why(?: does that step work| did you do that| did you (?:flip|reverse|change)(?: (?:the )?(?:inequality sign|inequality|symbol|sign))?| does (?:the )?inequality(?: sign)? (?:flip|reverse|change))?|(?:can you )?(?:break (?:it|that|this) down|explain (?:it|that|this))|how did you get that|i don['’]?t understand)$/i.test(input)){
        return {text:current.reason??current.steps?.[0]??current.text,links:current.links,actions:followupActions,intent:'followup'};
      }
      const number=(input.match(/^where did (?:the |that )?([+\-−]?(?:\d+(?:\.\d+)?|\.\d+)) come from$/i)
        ??input.match(/^how did you get (?:the |that )?([+\-−]?(?:\d+(?:\.\d+)?|\.\d+))$/i))?.[1];
      if(number){
        const value=Number(number.replace('−','-'));
        const step=current.steps?.find(line=>(line.match(/[+\-−]?(?:\d+(?:\.\d+)?|\.\d+)/g)??[])
          .some(token=>Number(token.replace('−','-'))===value));
        if(step)return {text:step,links:current.links,actions:followupActions,intent:'followup'};
      }
    }
    const concept=algebraConceptHelp(input)??algebraConcept(input);
    if(concept)return remember(concept);
    const missing=clarify?algebraClarification(input):null;
    if(missing)return remember(missing);
    reset();
    return null;
  }
  return {respond,reset,hasContext:()=>current!==null};
}

