function unitReply(course,index){
  if(!units[course][index])return {topic:'biology-chapters',intent:'clarify',
    text:'The Astra study guide has six teaching units for BIOL '+course+'. Try Unit 1 to get started.',links:guidanceLinks};
  const [title,numbers]=units[course][index];
  const rows=numbers.map(number=>openStax.get(number));
  return {topic:'biology-chapters',title,intent:'source',text:'BIOL '+course+' · Astra Unit '+(index+1)+' · '+title+'. Choose an aligned OpenStax Biology 2e chapter to study.',
    steps:rows.map(row=>'Chapter '+row.number+' · '+row.title),
    links:rows.map(row=>openStaxSource(row.number)),actions:rows.map(row=>['Chapter '+row.number,lessonPrompt(row)])};
}

const ignoredWords=new Set('openstax campbell biology biol textbook book 2e 12e 2nd 12th edition chapter chapters ch please overview review explain recap help topic for is the of with can you me teach about what in on i read which study'.split(' '));
function chapterCandidates(query,number,book){
  const candidates=(book?[books[book]]:Object.values(books)).map(value=>value.get(number)).filter(Boolean);
  if(candidates.length<2)return candidates;
  const words=query.split(' ').filter(word=>word.length>=4&&!ignoredWords.has(word)&&!/\d/.test(word));
  const scores=candidates.map(row=>Math.max(...row.aliases.map(term=>words.filter(word=>includes(term,word)).length)));
  if(scores[0]===scores[1])return candidates;
  return [candidates[scores[0]>scores[1]?0:1]];
}
function chapterForTopic(query,book){
  const text=query.replace(/\b(?:what|which|chapter|chapters|in|is|are|textbook|book|the|biology|campbell|openstax|12e|2e)\b/g,' ').replace(/\s+/g,' ').trim();
  if(!text)return [];
  const find=rows=>[...rows.values()].map(row=>({row,score:Math.max(...row.aliases.filter(alias=>includes(text,alias)).map(alias=>alias.length),0)})).sort((a,b)=>b.score-a.score);
  return (book?[books[book]]:Object.values(books)).flatMap(rows=>{
    const ranked=find(rows);
    if(!ranked[0].score||ranked[0].score===ranked[1]?.score)return [];
    return [ranked[0].row];
  });
}
function choose(rows){
  return {topic:'biology-chapters',intent:'clarify',
    text:rows.map(label).join('. ')+'. Which book are you using?',
    links:guidanceLinks,actions:rows.map(row=>[editions[row.book],lessonPrompt(row)])};
}

