 if(name==='img')return node.alt?[{tag:'p',children:['Image · '+node.alt]}]:[];
 if(name==='form'){
  const output=node.querySelector('[role=status]:not([hidden])');
  const result=output?contentOf(output,base,depth+1):[];
  if(!result.some(x=>typeof x==='string'?x.trim():x.children?.length))return [];
  const given=[...node.querySelectorAll('.exam-template-fields label')].map(label=>{
   const input=label.querySelector('input');
