  }).filter(Boolean);
  return [...(given.length?[{tag:'p',children:[given.join(' · ')]}]:[]),...result];
 }
 const children=[...node.childNodes].flatMap(child=>contentOf(child,base,depth+1));
 const tag=name==='details'?'section':name==='summary'?'h5':tags.has(name)?name:null;
 if(!tag)return children;
 const cls=[...node.classList].filter(c=>retainedClasses.has(c)).join(' ');
 const href=tag==='a'?safeLink(node.getAttribute('href'),base):undefined;
