export function snapshotConversation(log){
 const rows=[...log.querySelectorAll('.chat-message.user,.chat-message.assistant:not(.chat-working)')];
 if(!rows.some(row=>row.classList.contains('user')))return null;
 const doc=log.ownerDocument;
 const first=rows.find(row=>row.classList.contains('user'));
 const firstQuestion=first.dataset.questionText??first.querySelector('p')?.textContent??'BridgeAssist conversation';
 const title=firstQuestion.replace(/\s+/g,' ').trim().slice(0,96)||'BridgeAssist conversation';
 const messages=rows.map(row=>({
  role:row.classList.contains('user')?'user':'assistant',
  content:[...row.childNodes].filter(child=>child!==row.querySelector('h3')).flatMap(child=>contentOf(child,doc.baseURI))
 })).filter(row=>row.content.length);
 const now=new Date();
 return {v:1,id:doc.defaultView?.crypto?.randomUUID?.()??String(now.getTime()),savedAt:now.toISOString(),title,messages};
}

function validSnapshot(record){
 return record?.v===1&&typeof record.id==='string'&&typeof record.title==='string'&&Number.isFinite(Date.parse(record.savedAt))&&Array.isArray(record.messages);
}
export function savedTranscripts(storage){
 const raw=storage.getItem(storageKey);
 if(!raw)return [];
 const entries=JSON.parse(raw);
