}
export function storeTranscript(storage,record){
 if(!validSnapshot(record))throw TypeError('No conversation to save.');
 const previous=savedTranscripts(storage);
 const content=JSON.stringify(record.messages);
 const same=previous.find(item=>JSON.stringify(item.messages)===content);
 const saved=same?{...record,id:same.id}:record;
 storage.setItem(storageKey,JSON.stringify([saved,...previous.filter(item=>item.id!==saved.id)]));
 return saved;
}
export function removeTranscript(storage,id){
 storage.setItem(storageKey,JSON.stringify(savedTranscripts(storage).filter(item=>item.id!==id)));
}

export function renderTranscript(record,doc){
 if(!validSnapshot(record))throw TypeError('Invalid saved conversation.');
 const page=doc.createElement('article');page.className='bridgeassist-transcript';
 const title=doc.createElement('h1');title.textContent='BridgeAssist conversation';page.append(title);
 const subtitle=doc.createElement('p');subtitle.className='transcript-date';
 subtitle.textContent=timestamp.format(new Date(record.savedAt));page.append(subtitle);
 const append=(parent,child,depth)=>{
  if(typeof child==='string'){parent.append(child);return;}
  if(depth>24||!child||!tags.has(child.tag)||!Array.isArray(child.children))return;
  if(child.tag==='a'&&!safeLink(child.href)){for(const nested of child.children)append(parent,nested,depth+1);return;}
  const element=doc.createElement(child.tag);
  if(child.cls&&typeof child.cls==='string')element.className=child.cls.split(/\s+/).filter(c=>retainedClasses.has(c)).join(' ');
  if(child.tag==='a'){element.href=safeLink(child.href);element.rel='noopener noreferrer';}
  for(const nested of child.children)append(element,nested,depth+1);
  parent.append(element);
 };
 for(const turn of record.messages){
  if(!Array.isArray(turn?.content)||!['user','assistant'].includes(turn.role))continue;
  const section=doc.createElement('section');section.className='transcript-turn transcript-'+turn.role;
  const name=doc.createElement('h2');name.textContent=turn.role==='user'?'You':'BridgeAssist';section.append(name);
  for(const node of turn.content)append(section,node,0);
  page.append(section);
 }
 return page;
}

