export function mountChatUnloadGuard(w,log,{isDirty,onChange}){
 let listening=false,allowOne=false,expiry;
 const revoke=()=>{allowOne=false;if(expiry!==undefined)w.clearTimeout(expiry);expiry=undefined;};
 const beforeUnload=event=>{
  if(allowOne){revoke();return;}
  if(!isDirty())return;
  event.preventDefault();
  event.returnValue=true;
 };
 const refresh=()=>{
  const dirty=isDirty();
  if(dirty!==listening){
   if(dirty)w.addEventListener('beforeunload',beforeUnload);
   else{w.removeEventListener('beforeunload',beforeUnload);revoke();}
   listening=dirty;
  }
  onChange?.(dirty);
 };
 const approveLeave=()=>{
  revoke();allowOne=true;
  expiry=w.setTimeout(revoke,1000);
 };
 // Only top-level conversation changes count as new turns. Opening a resource or diagram doesn't undo a save.
 if(w.MutationObserver)new w.MutationObserver(refresh).observe(log,{childList:true});
 refresh();
 return {refresh,approveLeave};
}

