import {chemistryChapterEntries,chemistryChapterScope,chemistryChapterFollowup} from './learner-chemistry-chapters.mjs';

const normalize = value=>String(value??'').normalize('NFKC').toLowerCase().replace(/[’']/g,'').replace(/[^a-z0-9]+/g,' ').trim();
const named = 'OpenStax Chemistry 2e';
const sourceFor=(number)=>[named+' · Chapter '+number,'https://openstax.org/books/chemistry-2e/pages/'+number+'-introduction'];
export function createChemistryChapterCoach(){
  let chapter,card,checking=false;
  const reset=()=>{chapter=undefined;card=undefined;checking=false;};
  const all=(chapterNumber)=>chemistryChapterEntries.filter(item=>item.chapter===chapterNumber);
  const prompt=(n)=>'Study CHEM 1411 OpenStax Chemistry 2e chapter '+n;
  const teach=(title)=>'Teach me the CHEM 1411 topic '+title;
  const list=()=>({
    topic:'chemistry-chapters',title:'CHEM 1411 chapter guide',intent:'source',
    text:'This guide follows OpenStax Chemistry 2e chapters 1–11, the reference sequence mapped to the CHEM 1411 tutoring bank. Your instructor may teach them in a different order.',
    steps:chemistryChapterScope.chapters.map((title,i)=>(i+1)+'. '+title),
    links:[chemistryChapterScope.syllabus],
    actions:chemistryChapterScope.chapters.map((title,i)=>['Chapter '+(i+1)+' · '+title,prompt(i+1)])
  });
  const showCard=(row,intent='definition',value=row.answer)=>{
    chapter=row.chapter;card=row;checking=false;
    return {topic:row.id,title:row.title,intent,text:value,
      formula:intent==='definition'?row.formula:undefined,
      example:intent==='definition'?row.example:undefined,
      links:[row.source],
      actions:[['Break it down','Break it down'],['Why it matters','Why does it matter?'],['Try a chapter check','Give me a chapter check']]}
  };
  function choose(n){
    const title=chemistryChapterScope.chapters[n-1];
    if(!title){reset();return {topic:'chemistry-chapters',intent:'clarify',text:'The CHEM 1411 guide covers OpenStax Chemistry 2e chapters 1–11. Share your lecture topic if your chapter numbers differ.',actions:[['List CHEM 1411 chapters','List CHEM 1411 chapters']]};}
    chapter=n;card=undefined;checking=false;
    const chosen=all(n);
    return {topic:'chemistry-chapters',title,intent:'definition',
      text:'OpenStax Chemistry 2e · Chapter '+n+' · '+title+'. '+chosen[0].simple,
      steps:chosen.map(row=>row.title+' — '+row.simple),
      links:[sourceFor(n),...chosen.map(row=>row.source)],
      actions:[...chosen.map(row=>[row.title,teach(row.title)]),['Try a chapter check','Give me a chapter check'],...(n<11?[['Next chemistry chapter',prompt(n+1)]]:[])]};
  }
  function respond(raw,course=''){
    const q=normalize(raw);
    if(!q||/\b(?:biol|bio|biology) ?(?:1406|1407)\b/.test(q)||/\bbiology (?:2e|chapter)\b/.test(q)||
      /\b(?:download|pdf|handout|mock exam|exam style)\b/.test(q)){reset();return null;}
    const explicit= /\b(?:chem ?1411|chemistry 2e|chemistry chapter|openstax chemistry|general chemistry)\b/.test(q) || normalize(course)==='chem 1411';
    const n=q.match(/\b(?:chapter|ch) ?(\d{1,2})\b/)?.[1];
    if(n&&(explicit||chapter))return choose(Number(n));
    if(explicit&&/\bchapters\b/.test(q)){reset();return list();}
    if(explicit&&/\btopic\b/.test(q)){
      const name=q.split('topic ').at(-1);
      const found=chemistryChapterEntries.find(row=>normalize(row.title)===name);
      if(found)return showCard(found);
    }
    if(!chapter)return null;
    const row=card??all(chapter)[0];
    const help=chemistryChapterFollowup(row.id,raw);
    if(help)return {...help,intent:'followup'};
    if(/^(?:give me |show me )?(?:a )?(?:(?:quick|chapter) )?check$/.test(q)){
      checking=true;
      return {topic:row.id,title:row.title,intent:'hint',
        text:'Try explaining this in your own words before checking the response.',
        question:'For '+row.title.toLowerCase()+', what clue would tell you which setup or explanation to use?',
        links:[row.source],actions:[['Show the explanation','Show the answer']]};
    }
    if(checking&&/^(?:show (?:me )?(?:the )?answer|i (?:think|got|would)|my answer|why)\b/.test(q)){
      checking=false;
      return showCard(row,'followup',row.answer);
    }
    if(/^(?:can you )?(?:break (?:this|it|that) down|explain (?:this|it|that) again)$/.test(q))return showCard(row,'followup',row.simple);
    if(/^(?:give|show) me (?:an|the) example$/.test(q))return showCard(row,'followup',row.example);
    if(/^(?:go to )?(?:the )?(?:next|previous) (?:chemistry )?chapter$/.test(q))return choose(chapter+(/\bprevious\b/.test(q)?-1:1));
    if(q.length>12)reset();
    return null;
  }
  return {respond,reset};
}

