function parseWaterReaction(q){
 const hydrogen=examined(q,'g(?:rams?)?\\s*(?:of\\s*)?(?:h2|hydrogen)\\b');
 const oxygen=examined(q,'g(?:rams?)?\\s*(?:of\\s*)?(?:o2|oxygen)\\b');
 if(!hydrogen||!oxygen||!/h2o|water/.test(q)||!/2\s*h2\s*\+\s*(?:1\s*)?o2\s*(?:→|->|=>|=)\s*2\s*h2o/.test(q))return null;
 if(!(Number(hydrogen)>0&&Number(oxygen)>0))return null;
 const h=+hydrogen/2.016,o=+oxygen/32.00, reaction=Math.min(h/2,o);
 const digits=Math.min(significant(hydrogen),significant(oxygen),4);
 const tie=Math.abs(h/2-o)<1e-12;
 return {hydrogen,oxygen,h,o,reaction,digits,tie,limit:tie?'Both reactants':h/2<o?'H₂':'O₂',water:reaction*2*18.015};
}
function parseGas(q){
 const moles=examined(q,'mol(?:es?)?\\b');
 const celsius=examined(q,'(?:°\\s*)?(?:degrees?\\s*)?(?:c\\b|celsius\\b)',temp);
 const kelvin=examined(q,'(?:k\\b|kelvin\\b)',temp);
 const liters=examined(q,'(?:l\\b|lit(?:er|re)s?\\b)');
 if(!moles||(!celsius&&!kelvin)||!liters)return null;
 const k=celsius!==undefined?+celsius+273.15:+kelvin;
 if(!(+moles>0&&k>0&&+liters>0))return null;
 const temperatureDigits=celsius!==undefined?Math.min(6,Math.max(1,Math.floor(Math.log10(k))+1+(celsius.split('.')[1]?.length??0))):significant(kelvin);
 const digits=Math.min(significant(moles),significant(liters),temperatureDigits,6);
 const [,unit,r]=pressureUnits.find(([pattern])=>pattern.test(q))??[null,'atm',0.082057];
 return {moles,celsius,k,liters,digits,unit,r,pressure:+moles*r*k/+liters};
}

