  formula:'2 H₂ + O₂ → 2 H₂O',
  unitWork:[
   {label:'Convert the hydrogen mass to moles',chain:[fraction(measured(p.hydrogen,'g H₂',true)),fraction(measured('1','mol H₂'),measured('2.016','g H₂',true))],result:fmt(p.h,p.digits)+' mol H₂'},
   {label:'Convert the oxygen mass to moles',chain:[fraction(measured(p.oxygen,'g O₂',true)),fraction(measured('1','mol O₂'),measured('32.00','g O₂',true))],result:fmt(p.o,p.digits)+' mol O₂'}
  ],
  steps:[
   'Every time the equation goes once in mole amounts, it needs 2 mol H₂ and 1 mol O₂. So compare '+round(p.h,5)+' ÷ 2 with '+round(p.o,5)+' ÷ 1.',
   tie?'The ratios match, so neither reactant is left over in this ideal calculation.':'The smaller ratio is for '+p.limit+', so it runs out first. Comparing grams alone would not account for either molar mass or the reaction ratio.',
   'The reaction produces 2 mol H₂O for every time it goes once in mole amounts. That gives '+fmt(2*p.reaction,p.digits)+' mol H₂O, or '+fmt(p.water,p.digits)+' g of theoretical product. Keep guard digits until the final rounding.'
  ],answer:tie?'Both reactants are used up together.':p.limit+' is limiting.',links:[yieldSource],actions:limitActions};
}
function gasReply(p,explainLimits=true){
 const base={topic:'ideal-gas-law',title:'Ideal gas law',intent:'worked-example',links:[idealSource,realSource],actions:gasActions};
 const realism='Use PV = nRT as a model for a dilute gas, well away from condensation. At low temperatures and high pressures, particle attractions and the space the particles occupy can matter.';
 if(!p)return {...base,text:realism,
  steps:['Attractions can make real pressure lower than the ideal prediction. At very high density, crowding can instead make the pressure higher.','For one state, use P = nRT/V. To compare two states, check which quantities, such as the amount of gas, are held constant.']};
 return {...base,text:explainLimits?realism:'Use the ideal gas law for one state when you know amount, volume, and temperature and need the pressure.',formula:'P = nRT / V',
  unitWork:[{label:'Substitute in liters, moles, and kelvin',chain:[
   fraction(measured(p.moles,'mol',true)),
   {top:{value:String(p.r),units:[{text:'L',cancel:true},{text:p.unit,cancel:false}]},bottom:{value:'1',units:[{text:'mol',cancel:true},{text:'K',cancel:true}]}},
   fraction(measured(String(Number(p.k.toFixed(8))),'K',true)),
   fraction({value:'1',units:[]},measured(p.liters,'L',true))],result:fmt(p.pressure,p.digits)+' '+p.unit}],
  steps:[
   ...(p.celsius===undefined?[]:['Convert '+p.celsius+' °C to kelvin by adding 273.15. Use '+Number(p.k.toFixed(8))+' K in the calculation before rounding.']),
   'Use a value of R that matches liters and the requested pressure unit. The matching mol, K, and L cancel. The unit left is '+p.unit+'.',
   ...(explainLimits?['Attractions can lower real pressure relative to this answer. At sufficiently high density, crowding can push it higher instead.']:[])
