const follow= (topic,text,links,extra={})=>({topic,title:topic==='ideal-gas-law'?'Ideal gas law':'Limiting reactant',intent:'followup',text,links,...extra});

export function createChemistryCoach(){
 let active=null;
 function respond(raw){
  const q=clean(raw);
  const hint= /\b(?:hint only|without (?:telling|giving)(?: me)? the answer|don.t (?:tell|give)(?: me)? the answer)\b/.test(q);
  const water=parseWaterReaction(q);
  if(water){
   active={water};
   if(hint)return follow('limiting-reactant','Start by converting both given masses to moles. Then divide the hydrogen moles by 2 and the oxygen moles by 1. Which ratio is smaller?',[yieldSource],{actions:[action('Show the work','Show the worked solution')]});
   return waterReply(water);
  }
  const gasRequest=/\b(?:ideal gas law|p\s*v\s*=\s*n\s*r\s*t)\b/i.test(q);
  const gasConditions=/\b(?:fail(?:s|ure)?|poor approximation|breaks? down|non[- ]ideal|real gas|deviat\w*)\b/.test(q);
  const p=gasRequest?parseGas(q):null;
  if(gasRequest&&(gasConditions||(p&&/\b(?:pressure|find p|(?:in|give) (?:atm|kpa|torr|bar))\b/.test(q)))){
   if(!p&&active?.gas){
    return {...gasReply(null),intent:'followup'};
   }
   active={gas:p,limits:gasConditions};
   if(hint&&p)return follow('ideal-gas-law','Start with P = nRT/V. Convert temperature to kelvin, then check the units of R against your volume and desired pressure.',[idealSource],{actions:[action('Show the work','Show the worked solution')]});
   return gasReply(p,gasConditions);
  }
  if(active?.water){
   const p=active.water;
   const reply=(line,extra)=>follow('limiting-reactant',line,[yieldSource],extra);
   if(/^show (?:the |your )?(?:(?:worked )?solution|work|answer)\b/.test(q))return waterReply(p);
   if(/\bdivid\w*\b.*\bcoefficient|\bwhy\s+(?:did|do)\s+(?:i|you|we)\s+divide\b/.test(q)){
    return reply('The coefficient is how many moles of that reactant one run of the balanced equation requires. Divide available moles by moles needed per run. For H₂, '+round(p.h,5)+' ÷ 2 tells you how many runs the hydrogen can supply. For O₂, compare '+round(p.o,5)+' ÷ 1. The smaller result runs out first.');
   }
   if(/\b(?:difference|mean|definition)\b.*\blimiting reactant\b.*\bexcess reactant\b/.test(q)){
    return reply('The limiting reactant is used up first and sets the maximum product. The excess reactant is available in more than the balanced equation requires for that amount of product. '+(p.tie?'These amounts match exactly, so neither is in excess.':p.limit+' is limiting in this example.'));
   }
   if(/\b(?:another way|compar\w* .*water|compar\w* (?:grams|moles) of product|how much water each)\b/.test(q)){
    if(/\bgrams\b/.test(q))return reply('Yes. Convert each reactant into the mass of the same product. H₂ alone could make '+fmt(p.h*18.015,p.digits)+' g H₂O. O₂ alone could make '+fmt(2*p.o*18.015,p.digits)+' g H₂O. Compare the two masses of water, not the original reactant masses.');
    return reply('Yes. Use the coefficients to predict the same product from each reactant. H₂ alone could make '+fmt(p.h,p.digits)+' mol H₂O. O₂ alone could make '+fmt(2*p.o,p.digits)+' mol H₂O. The smaller prediction sets the yield.');
   }
   if(/\b(?:volumes?|liters?)\b.*\b(?:gases?|instead of masses)\b/.test(q)){
    return reply('Compare gas volumes divided by their coefficients only if the gases are at the same temperature and pressure and behave ideally. If their temperatures or pressures differ, first calculate moles separately with n = PV/RT. Then compare moles divided by coefficients.');
   }
   if(/\bdimensional analysis\b/.test(q)){
    const product=(quantity,mass,reactant,bottom)=>[
     fraction(measured(quantity,'g '+reactant,true)),
     fraction(measured('1','mol '+reactant,true),measured(mass,'g '+reactant,true)),
     fraction(measured('2','mol H₂O'),measured(bottom,'mol '+reactant,true))];
    return reply('Make the same product on both lines so the answers are comparable. Start with each measured mass and follow the units to moles of water. The smaller amount wins.',
     {unitWork:[
      {label:'From hydrogen',chain:product(p.hydrogen,2.016,'H₂','2'),result:fmt(p.h,p.digits)+' mol H₂O'},
      {label:'From oxygen',chain:product(p.oxygen,'32.00','O₂','1'),result:fmt(2*p.o,p.digits)+' mol H₂O'}]});
   }
   if(/\b(?:buffer|titration)\b/.test(q))return reply('In an acid–base titration, the balanced reaction tells you the mole ratio at equivalence. Before or after that point, the limiting reactant is consumed and the excess may affect the pH. A solution is a buffer only when the composition includes suitable amounts of a weak acid and its conjugate base, or the corresponding weak-base pair.');
   if(/\bweigh precisely\b|\bmeasure accurately\b/.test(q))return reply('Measure the quantities used in the calculation to the precision your procedure requires. Uncertainty in the limiting reactant carries directly into the predicted product. You still need enough information about the other reactant to establish that it is actually in excess.');
   if(/\b(?:left over|leftover|in excess|how much .*left|remaining)\b/.test(q)){
    const h=Number(p.hydrogen)-p.reaction*2*2.016,o=Number(p.oxygen)-p.reaction*32;
    const symbol=h>1e-10?'H₂':o>1e-10?'O₂':'neither';
    if(symbol==='neither')return reply('Neither reactant remains in the ideal calculation. The starting amounts match the balanced equation’s mole ratio.');
    const mass=symbol==='H₂'?+p.hydrogen:+p.oxygen, used=symbol==='H₂'?p.reaction*2*2.016:p.reaction*32;
    const original=symbol==='H₂'?p.hydrogen:p.oxygen;
    const places=original.split('.')[1]?.length??0;
    return reply('Subtract the amount used from the amount you started with. Keep the unrounded consumed mass until the subtraction.',{formula:original+' g − '+round(used,6)+' g = '+(mass-used).toFixed(places)+' g '+symbol,answer:(mass-used).toFixed(places)+' g '+symbol+' remains'});
   }
   if(/\bpercent yield\b/.test(q)){
    const actual=examined(q,'g(?:rams?)?\\b');
    if(!actual)return reply('Percent yield compares the actual product mass you collected to the theoretical mass. Divide the actual mass by '+fmt(p.water,p.digits)+' g H₂O and multiply by 100. What actual mass did you get?');
    const pct=+actual/p.water*100;
    return reply('Use the theoretical yield from the limiting reactant in the denominator. Carry its unrounded value into the calculation.',{formula:'percent yield = actual yield ÷ theoretical yield × 100',
     unitWork:[{label:'Compare the masses of actual and theoretical product',
      chain:[fraction(measured(actual,'g H₂O',true),measured(round(p.water,6),'g H₂O',true)),fraction({value:'100',units:[]})],
      result:fmt(pct,Math.min(significant(actual),p.digits))+'%'}]});
   }
   if(/\bsignificant figures|sig figs|rounding\b/.test(q))return reply('For the products and quotients, the least precise measured input sets the result to '+p.digits+' significant figures. The coefficients are exact counts. Keep a few extra digits until the final step.');
   if(/\btheoretical yield\b.*\b(?:actual|versus)|\bactual yield\b.*\btheoretical\b/.test(q))return reply('The theoretical yield is the most product the limiting reactant allows, '+fmt(p.water,p.digits)+' g H₂O here. Actual yield is how much a measurement says was collected.');
   if(/\b(?:three|3|more than two) reactants\b/.test(q))return reply('Use the same comparison for every reactant. Convert each given amount to moles and divide by its own coefficient. The smallest result is the first constraint. Equal smallest values mean those reactants are used up together in the ideal model.');
   if(/\bwhy\b.*\b(?:yield|reactions?)\b.*\b(?:less|lower)\b/.test(q))return reply('The theoretical yield assumes the intended reaction goes as far as the limiting reactant allows and that you recover all the product. Incomplete reaction, side products, and loss during collection can make the measured yield lower.');
  }
  if(active&&Object.hasOwn(active,'gas')){
   const p=active.gas;
   const reply=(line,extra)=>follow('ideal-gas-law',line,[idealSource,realSource],extra);
   if(p&&/^show (?:the |your )?(?:(?:worked )?solution|work|answer)\b/.test(q))return gasReply(p,active.limits);
   if(/\bkelvin\b|why .*celsius/.test(q)&&!/double/.test(q))return reply('Gas-law proportionality uses absolute temperature, measured from absolute zero. Zero Celsius is not zero thermal energy. To convert Celsius to kelvin, add 273.15.'+(p?.celsius!==undefined?' Here '+p.celsius+' °C becomes '+Number(p.k.toFixed(8))+' K before rounding.':''));
   if(/\b(?:value of r|which r|units of r|does r mean|meaning of r|why .*\br\b)\b/.test(q))return reply('R is the gas constant. It connects the thermal energy scale per mole to the pressure–volume product of an ideal gas. Its numerical value changes with the units. '+(p?'For this calculation, use '+p.r+' L·'+p.unit+'/(mol·K) so that the pressure comes out in '+p.unit+'.':'Use 0.082057 L·atm/(mol·K) with liters, moles, kelvin, and atmospheres.'));
   if(/\b(?:two states|initial and final|before and after)\b/.test(q))return reply('Write PV = nRT for each state. If n is fixed, compare P₁V₁/T₁ with P₂V₂/T₂. If temperature is also fixed, the T terms cancel and you get Boyle’s law. Keep temperature in kelvin. If n changes, do not assume the two P V/T values are equal.');
   if(/\bstp\b|\bstandard temperature and pressure\b/.test(q))return reply('Check the convention specified in your problem. A common classroom definition uses 0 °C and 1 atm. Another uses 0 °C and 1 bar. Those pressures are close but not identical, so the corresponding molar volumes are different.');
   if(/\bkinetic molecular\b|\bwhy pressure rises\b/.test(q))return reply('At fixed volume and amount, heating increases the average kinetic energy of the particles. More rapid and stronger collisions with the walls transfer more momentum per unit time, so the pressure rises.');
   if(p&&/\bdensity\b/.test(q)){
    const molarMass=examined(q,'g\\s*(?:/|per\\s+)\\s*mol\\b');
    if(molarMass&&+molarMass>0){
     const answer=fmt(+p.moles/+p.liters*+molarMass,Math.min(significant(p.moles),significant(p.liters),significant(molarMass)))+' g/L';
     return reply('Density is mass per volume. You already have the gas amount and the container volume. Multiply moles per liter by the molar mass to get grams per liter.',
      {formula:'density = (n / V) × molar mass',
      unitWork:[{label:'Cancel mol to leave grams per liter',chain:[fraction(measured(p.moles,'mol',true),measured(p.liters,'L')),fraction(measured(molarMass,'g'),measured('1','mol',true))],result:answer}]});
    }
   }
   if(/\b(?:dalton|partial pressures?)\b/.test(q))return reply('The ideal-gas model treats the pressure contributed by each gas as if that gas filled the container alone at the same temperature. Add those partial pressures to get the total. For one component, use its own amount in Pᵢ = nᵢRT/V.');
   if(/\b(?:over water|water vapor pressure|wet gas)\b/.test(q))return reply('If the gas in the container includes water vapor, its total pressure includes that vapor. Subtract the water-vapor pressure at the actual temperature to get the dry gas pressure.');
   if(gasConditions||/\bvan der waals\b|\bcompressibility\b/.test(q))return reply('Attractions between particles can lower the pressure relative to the ideal prediction. Crowding at high density can raise it. In the van der Waals model, a corrects for attractions and b for the volume particles exclude. Z = PV/(nRT) is 1 for an ideal gas and can fall below or rise above 1 for real gases.');
   if(/\bdouble\b.*\b(?:temp|kelvin)|\b(?:temp|kelvin)\w*\b.*\bdouble\b/.test(q))return reply('With volume and amount fixed, doubling the temperature in kelvin doubles the ideal pressure. Doubling the Celsius number does not double the pressure.'+(p?' For this example, doubling '+Number(p.k.toFixed(8))+' K changes the predicted pressure to '+fmt(2*p.pressure,p.digits)+' '+p.unit+'.':''));
   if(p&&/\b(?:how did you get|where .*pressure .*come|show .*pressure|break (?:it|that|this) down)\b/.test(q))return {...gasReply(p,active.limits),text:'For this container, pressure is the unknown. Multiply amount, gas constant, and kelvin temperature, then divide by the volume.'};
  }
  // An explicit new topic must not inherit the quantities from the last problem.
  if(!/^(?:why|how|what about|can you break|show|where did)\b/.test(q)||/\b(?:mitosis|genetics|photosynthesis|hess|molarity|unit conversion)\b/.test(q))active=null;
  return null;
 }
 return {respond,reset:()=>{active=null;}};
}

