export function examNumberTemplate(item){
  if(!item||item.calculation===false)return null;
  const key=item.chapterId==='measurements'&&/in liters/i.test(item.question)?'measurements-volume':item.chapterId;
  return Object.hasOwn(templates,key)?templates[key]:null;
}

export function evaluateNumberTemplate(template,inputs){
  if(!template||!Array.isArray(inputs)||inputs.length!==template.fields.length)return {error:'Enter a value for each field.'};
  const numbers=inputs.map((input,i)=>{
    const s=String(input).trim().replaceAll('−','-');
    if(!/^[+-]?(?:(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i.test(s))return NaN;
    const v=Number(s.replaceAll(',',''));
    if(!Number.isFinite(v)||Math.abs(v)>1e10)return NaN;
    const rule=template.fields[i].rule;
    if(rule==='positive'&&v<=0||rule==='nonnegative'&&v<0||
       rule==='count'&&(!Number.isSafeInteger(v)||v<0)||rule==='positive-count'&&(!Number.isSafeInteger(v)||v<=0)||
       rule==='percent'&&(v<0||v>100))return NaN;
    return v;
  });
  if(numbers.some(v=>!Number.isFinite(v)))return {error:'Enter valid numbers in the labelled units. Counts must be whole, and percentages must be from 0 to 100.'};
  const value=template.calculate(...numbers);
  if(!Number.isFinite(value))return {error:template.invalidSetup||'Check how the inputs relate. For example, a part cannot exceed its total.'};
  return {value,text:format(value)+(template.unit?' '+template.unit:''),setup:template.explain(...numbers)};
}

export function renderExamHint(block,item,typeset){
  const guide=buildExamHint(item);
  const d=block.ownerDocument;
  const add=(tag,value,parent=block)=>{const n=d.createElement(tag);if(value)n.textContent=value;parent.append(n);return n;};
  if(guide.clues.length){
    add('h4','Clues in the wording');
    const clues=add('dl','');clues.className='learner-clues';
    for(const {quote,meaning} of guide.clues){add('dt','“'+quote+'”',clues);add('dd',meaning,clues);}
  }
  add('h4','Start with');
  add('p',guide.start);
  add('h4','Choose the next operation');
  add('p',guide.method);
  if(guide.formula){const line=add('p','');line.className='learner-formula';typeset(line,guide.formula);}
  add('h4','Check before choosing');
  add('p',guide.check);
}

export function renderExamNumberTemplate(block,item,typeset){
  const template=examNumberTemplate(item);
  if(!template)return false;
  const d=block.ownerDocument;
  const add=(tag,value,parent=block)=>{const n=d.createElement(tag);if(value)n.textContent=value;parent.append(n);return n;};
  add('h4',template.title+' · Try your own numbers');
  const formula=add('p',''); formula.className='learner-formula'; typeset(formula,template.formula);
  const form=add('form','');form.className='exam-template';form.setAttribute('aria-label','Calculate using your own numbers');
  add('p','Enter values in the units shown. This calculator is separate from your practice question.',form);
  const grid=add('div','',form);grid.className='exam-template-fields';
  const inputs=template.fields.map(({label,unit})=>{
    const labelled=add('label',label+(unit?' ('+unit+')':''),grid);
    const input=add('input','',labelled);input.type='text';input.inputMode='decimal';input.autocomplete='off';input.required=true;input.maxLength=24;
    return input;
  });
  const button=add('button','Calculate with my values',form);button.type='submit';
  const panel=add('div','',form);panel.setAttribute('role','status');panel.setAttribute('aria-live','polite');
  form.addEventListener('submit',event=>{
    event.preventDefault();
    const result=evaluateNumberTemplate(template,inputs.map(input=>input.value));
    panel.replaceChildren();
    if(result.error){add('p',result.error,panel);return;}
    const setup=add('p','',panel), output=add('p','',panel);
    typeset(setup,result.setup);
    output.className='learner-formula';typeset(output,'Result ≈ '+result.text);
    add('p','Round to the precision your problem asks for.',panel);
  });
  return true;
}

