async function read(path){
  const saved=cache.get(path);
  if(saved)return saved;
  const pending=fetch(root+path).then(response=>{
    if(!response.ok)throw Error('Expanded practice did not load');
    return path.endsWith('.bin')?new Response(response.body.pipeThrough(new DecompressionStream('gzip'))).json():response.json();
  }).catch(error=>{cache.delete(path);throw error;});
  cache.set(path,pending);
  if(cache.size>24)cache.delete(cache.keys().next().value);
  return pending;
}

export const expandedManifest=()=>read('manifest.json');

export async function studyRecord(position){
  if(position<firstPosition)return libraryRecord(position);
  const offset=position-firstPosition;
  const {total,shardSize}=await expandedManifest();
  if(!Number.isInteger(offset)||offset<0||offset>=total)return null;
  return (await read('records/'+Math.floor(offset/shardSize)+'.bin'))[offset%shardSize];
}

export async function exactExpandedPractice(query,course=''){
  if(query.length<12||query.length>1600)return null;
  const key=normalizeQuestion(query);
  const matches=(await read('exact/'+bucketFor(key)+'.bin'))[key];
  if(!Number.isInteger(matches)&&!Array.isArray(matches))return null;
  const candidates=await Promise.all([matches].flat().map(value=>studyRecord(firstPosition+value)));
  const record=candidates.find(item=>item&&(!course||item.courses.includes(course))&&exactQuestion(item.question)===exactQuestion(query));
  return record?{record}:null;
}

export async function expandedPracticePage({query='',course='',page=1,exclude=[]}={}){
  const {total,shardSize,collections}=await expandedManifest();
  const scope=collections.filter(item=>!course||item.course===course);
  const words=libraryTokens(query);
  const limit=20;
  const blocked=new Set(exclude);
  let positions=[];
  if(words.length){
    const topics=scope.flatMap(item=>item.families.map(family=>{
      const tags=new Set(libraryTokens(family.id+' '+(aliases[family.id]??'')));
      return {family,score:words.filter(token=>tags.has(token)).length};
    }));
    const relevance=Math.max(...topics.map(item=>item.score),0);
    if(relevance<Math.ceil(words.length*.75))return {results:[],count:0,page:1,pageCount:1};
    const lists=await Promise.all(topics.filter(item=>item.score===relevance).map(({family})=>read(family.file)));
    positions=lists.flat();
  }else if(course||blocked.size!==0){
    positions=scope.flatMap(item=>Array.from({length:item.end-item.start},(_,index)=>item.start+index));
  }
  const filtered=words.length||course||blocked.size!==0;
  if(blocked.size)positions=positions.filter(offset=>!blocked.has(firstPosition+offset));
  const count=filtered?positions.length:total;
  const pageCount=Math.max(1,Math.ceil(count/limit));
  const current=Math.min(pageCount,Math.max(1,Math.floor(page)||1));
  const start=(current-1)*limit;
  const visible=filtered?positions.slice(start,start+limit):
    Array.from({length:Math.min(limit,count-start)},(_,index)=>start+index);
  const results=await Promise.all(visible.map(async offset=>{
    const chunk=await read('catalog/'+Math.floor(offset/shardSize)+'.bin');
    const [id,kind,index,topic,question,family]=chunk[offset%shardSize];
    return {id,kind,topic,question,family,position:firstPosition+offset,course:collections[index].course};
  }));
  return {count,page:current,pageCount,results};
}

const metrics = new Map([
 ['L',['volume',1]],['mL',['volume',1e-3]],['µL',['volume',1e-6]],
 ['g',['mass',1]],['kg',['mass',1e3]],['mg',['mass',1e-3]],['µg',['mass',1e-6]],['ng',['mass',1e-9]],
 ['m',['length',1]],['km',['length',1e3]],['cm',['length',1e-2]],['mm',['length',1e-3]],['µm',['length',1e-6]],['nm',['length',1e-9]],
 ['mol',['amount',1]],['mmol',['amount',1e-3]],['µmol',['amount',1e-6]],
 ['s',['time',1]],['min',['time',60]],['h',['time',3600]],
 ['K',['kelvin',1]],['J',['energy',1]],['kJ',['energy',1000]],
 ['Pa',['pressure',1]],['kPa',['pressure',1000]],['bar',['pressure',1e5]],['atm',['pressure',101325]],['torr',['pressure',101325/760]],
 ['particles',null],['molecules',null],['atoms',null],['cells',null]
]);
const supers={'⁰':'0','¹':'1','²':'2','³':'3','⁴':'4','⁵':'5','⁶':'6','⁷':'7','⁸':'8','⁹':'9','⁻':'-','⁺':'+'};
const num='[+\\-−]?(?:\\d{1,3}(?:,\\d{3})+(?:\\.\\d+)?|\\d+(?:\\.\\d*)?|\\.\\d+)';
const scientific = new RegExp('^('+num+')(?:[eE]([+-]?\\d{1,3})|\\s*[×*]\\s*10(?:\\^\\s*(?:\\(([+−-]?\\d{1,3})\\)|([+−-]?\\d{1,3}))|([⁰¹²³⁴⁵⁶⁷⁸⁹⁻⁺]{1,4})))?(?![\\d.])');

function splitTopLevel(text,separators){
 let depth=0,at=0;
 const result=[];
 for(let i=0;i<text.length;i++){
  const c=text[i];
  if(c==='(')depth++;
  else if(c===')'&&--depth<0)return null;
  else if(depth===0&&separators.includes(c)){
   // A multiplication sign in scientific notation belongs to the number.
   if((c==='×'||c==='*')&&/\d\s*$/.test(text.slice(at,i))&&
      /^\s*10(?:\^|[⁰¹²³⁴⁵⁶⁷⁸⁹⁻⁺])/.test(text.slice(i+1)))continue;
   result.push(text.slice(at,i).trim());at=i+1;
  }
 }
 if(depth!==0)return null;
 result.push(text.slice(at).trim());
 return result.every(Boolean)?result:null;
}
function unwrap(text){
 while(text.startsWith('(')&&text.endsWith(')')){
  let depth=0,index=0;
  for(;index<text.length;index++){
   if(text[index]==='(')depth++;
   else if(text[index]===')'&&--depth===0)break;
  }
  if(index!==text.length-1)break;
  text=text.slice(1,-1).trim();
 }
 return text;
}
const displayNumber=value=>{
 if(!value)return '0';
 return Math.abs(value)<0.00001||Math.abs(value)>=1e9?
  Number(value.toPrecision(10)).toExponential().replace(/e\+?(-?\d+)/,' × 10^($1)'):
  Number(value.toPrecision(11)).toString();
};
function quantity(raw){
 const text=unwrap(raw);
 const match=scientific.exec(text);
 if(!match)return null;
 const exponent=(match[2]??match[3]??match[4]??match[5]??'0')
  .replace(/[⁰¹²³⁴⁵⁶⁷⁸⁹⁻⁺]/g,c=>supers[c]).replace('−','-');
 const coefficient=Number(match[1].replaceAll(',','').replace('−','-'));
 const amount=coefficient*10**Number(exponent);
 if(!Number.isFinite(amount)||Math.abs(Number(exponent))>100)return null;
 const unitText=text.slice(match[0].length).trim().replace(/·/g,' ');
 const parts=unitText?unitText.split(/\s+/):[];
 if(parts.length>4)return null;
 const units=[];
 for(const rawUnit of parts){
  if(!metrics.has(rawUnit.replace(/[μµ]/g,'µ'))){
   if(!units.length||!/^(?:[A-Z][a-z]?[0-9₀-₉]*){1,12}$/.test(rawUnit)||units.at(-1).species)return null;
   units.at(-1).text+=' '+rawUnit;units.at(-1).species=rawUnit.normalize('NFKC');
   units.at(-1).key+=' '+units.at(-1).species;
  }else{
   const key=rawUnit.replace(/[μµ]/g,'µ');
   units.push({key,text:rawUnit,cancel:false});
  }
 }
 return {value:match[0].trim(),amount,units};
}

export function explicitUnitWork(input){
 const trimmed=String(input??'').trim().replace(/[?.]+$/,'').replace(/^(?:calculate|evaluate|check|simplify|solve)(?:\s+(?:my|this|the)\s+(?:setup|calculation|conversion|chain))?(?:\s*:\s*|\s+)/i,'');
 if(trimmed.length>1100||!/[×*/÷]/.test(trimmed))return null;
 const steps=splitTopLevel(trimmed,'×*');
 if(!steps||steps.length>12)return null;
 const chain=[];
 for(const step of steps){
  const factor=splitTopLevel(unwrap(step),'/÷');
  if(!factor||factor.length>2)return null;
  const top=quantity(factor[0]),bottom=factor[1]?quantity(factor[1]):undefined;
  if(!top||factor[1]&&!bottom)return null;
  chain.push({top,bottom});
 }
 if(!chain.some(f=>f.top.units.length||f.bottom?.units.length))return null;
 const dividedByZero=chain.some(f=>f.bottom?.amount===0);
 const result=chain.reduce((value,{top,bottom})=>value*top.amount/(bottom?.amount??1),1);
 if(dividedByZero||!Number.isFinite(result))return {
  topic:'dimensional-analysis',title:'Dimensional analysis',intent:'clarify',
  text:dividedByZero?'One denominator is zero, so this calculation is undefined. Check the copied conversion factor.':'The values are too large or small to combine reliably. Check the powers of ten.'
 };
 const allTop=chain.flatMap(f=>f.top.units);
 const allBottom=chain.flatMap(f=>f.bottom?.units??[]);
 for(const unit of allTop){
  const same=allBottom.find(other=>!other.cancel&&other.key===unit.key);
  if(same){same.cancel=true;unit.cancel=true;}
 }
 const simplify=units=>{
  const count=new Map();
  for(const unit of units.filter(i=>!i.cancel))count.set(unit.text,(count.get(unit.text)??0)+1);
  return [...count.entries()].map(([text,n])=>n===1?text:text+'^'+n).join('·');
 };
 const top=simplify(allTop),bottom=simplify(allBottom);
 const unit=bottom?(top||'1')+'/'+(bottom.includes('·')?'('+bottom+')':bottom):top;
 const unsupported=[];
 for(const f of chain){
  if(!f.bottom||f.top.units.length!==1||f.bottom.units.length!==1)continue;
  const a=f.top.units[0],b=f.bottom.units[0];
  const ma=metrics.get(a.key),mb=metrics.get(b.key);
  if(!ma||!mb||ma[0]!==mb[0]||a.key===b.key)continue;
  const x=f.top.amount*ma[1],y=f.bottom.amount*mb[1];
  if(Math.abs(x-y)>Math.max(Math.abs(x),Math.abs(y))*1e-10)unsupported.push(f.top.value+' '+a.text+' does not equal '+f.bottom.value+' '+b.text+'. If you meant this as a conversion factor, check the equality before trusting the result.');
 }
 const count=allTop.filter(x=>x.cancel).length;
 return {
  topic:'dimensional-analysis',title:'Dimensional analysis',intent:'worked',
  text:count?'Match each numerator unit with an identical denominator unit. The crossed-out pairs cancel.':'No identical units are on opposite sides of these fraction bars. Check whether any factor needs to be flipped.',
  unitChain:chain,
  steps:[...unsupported,unit?'The units left are '+unit+'.':'All units cancel here, leaving a number.','Combine the numbers on top and divide by the numbers below. Round only after the calculation.'],
  answer:(unsupported.length?'Your written expression gives ':'')+displayNumber(result)+(unit?' '+unit:''),
  links:[['OpenStax · Mathematical treatment of measurement results','https://openstax.org/books/chemistry-2e/pages/1-6-mathematical-treatment-of-measurement-results']],
  actions:[['Which units cancel?','Which units cancel?'],['What if I flip a factor?','What if I flip a factor?']]
 };
}

export function createExplicitUnitTutor(){
 let active;
 function respond(input){
  const next=explicitUnitWork(input);
  if(next){active=next;return next;}
  if(!active?.unitChain)return null;
  const q=String(input).toLowerCase().trim();
  if(/^(?:which|what) units (?:cancel|are left)\b/.test(q)){
   const names=[...new Set(active.unitChain.flatMap(f=>f.top.units.filter(u=>u.cancel).map(u=>u.text)))];
   return {topic:active.topic,title:active.title,intent:'followup',
    text:names.length?'The matching pairs are '+names.join(', ')+'. Each appears on top and bottom, so it divides out.':'There are no matching top-and-bottom unit pairs in this chain.',unitChain:active.unitChain,links:active.links};
  }
  if(/^(?:what if i flip|why (?:did|do|should) (?:i|you|we) flip)/.test(q))return {
   topic:active.topic,title:active.title,intent:'followup',
   text:'In a conversion, the unit you have belongs on the bottom of a factor so it cancels the unit already on top. If you flip that factor the wrong way, the old unit remains and the new unit can end up below the fraction line.',
   links:active.links
  };
  active=undefined;return null;
 }
 return {respond,reset(){active=undefined;}};
}

import {libraryManifest, libraryPage} from './full-library.mjs?v=library-4';
import {expandedManifest,expandedPracticePage} from './expanded-practice.mjs';

export async function mountStudyLibrary(host, openRecord, initial = {}) {
  const document = host.ownerDocument;
  const beforeMount = document.activeElement;
  host.className = 'learning-reply study-library-in-chat';
  host.innerHTML = `
    <p class="study-library-total" data-total hidden tabindex="-1"></p>
    <form class="study-library-search" data-search role="search" aria-label="Search study records">
      <div class="study-library-search-row">
        <label>Search by topic or question
          <input name="q" type="search" placeholder="Try mitosis or gas law" maxlength="1600">
        </label>
        <button type="submit" class="study-library-submit">Search</button>
      </div>
      <div class="study-library-filters">
        <label>Collection
          <select name="course"><option value="">All collections</option></select>
        </label>
        <label>Type
          <select name="type">
            <option value="">All types</option>
            <option value="question">Questions</option>
            <option value="practice">Practice</option>
            <option value="expanded">Expanded practice</option>
          </select>
        </label>
      </div>
    </form>
    <div class="study-library-result-bar">
      <p class="study-library-status" data-status role="status" tabindex="-1"></p>
      <form class="study-library-pager" data-pages aria-label="Result pages" hidden>
        <button type="button" data-previous aria-label="Previous page">Previous</button>
        <div class="study-library-page-jump">
          <input aria-label="Page number" name="page" type="text" inputmode="numeric" pattern="[0-9]+" maxlength="10" value="1" required>
          <span data-limit></span>
          <button type="submit" aria-label="Go to page">Go</button>
        </div>
        <button type="button" data-next aria-label="Next page">Next</button>
      </form>
    </div>
    <ul class="study-library-results" aria-label="Study results" role="list"></ul>
    <button class="study-library-page-return" type="button" data-page-return hidden>Page controls ↑</button>`;
  const search = host.querySelector('[data-search]');
  const pages = host.querySelector('[data-pages]');
  const query = search.elements.q;
  const collection = search.elements.course;
  const type = search.elements.type;
  const page = pages.elements.page;
  const status = host.querySelector('[data-status]');
  const resultBar = status.parentElement;
  const total = host.querySelector('[data-total]');
  const list = host.querySelector('.study-library-results');
  const previous = pages.querySelector('[data-previous]');
  const next = pages.querySelector('[data-next]');
  const limit = pages.querySelector('[data-limit]');
  const pageReturn = host.querySelector('[data-page-return]');
  const format = number => number.toLocaleString('en-US');
  let generation = 0;
  let current = 1;
  let activeFilters;

  function revealWithinChat(target) {
    const log = host.closest('.chat-log');
    if (!log) return;
    const viewport = log.getBoundingClientRect();
    const item = target.getBoundingClientRect();
    if (item.top < viewport.top + 12 || item.bottom > viewport.bottom - 12) {
      log.scrollTop += item.top - viewport.top - 12;
    }
  }

  function apply(view) {
    const results = document.createDocumentFragment();
    for (const item of view.results) {
      const row = document.createElement('li');
      const button = document.createElement('button');
      const detail = document.createElement('small');
      detail.textContent = (item.course === 'RESOURCES' ? 'Study resources' : item.course) +
        ' · ' + (item.kind === 'practice' ? 'Practice problem' : 'Question');
      button.type = 'button';
      button.append(detail, document.createTextNode(item.question));
      button.addEventListener('click', () => openRecord(item.position, item.kind === 'practice'));
      row.append(button);
      results.append(row);
    }
    list.replaceChildren(results);
    current = view.page;
    const label = view.count === 1 ? ' result' : ' results';
    status.textContent = view.count ? format(view.count) + label : 'No results. Try a shorter topic or a different collection.';
    if (view.pageCount > 1) {
      const announcement = document.createElement('span');
      announcement.className = 'study-library-sr';
      announcement.textContent = ' · Page ' + format(view.page) + ' of ' + format(view.pageCount);
      status.append(announcement);
    }
    pages.hidden = view.pageCount <= 1;
    pageReturn.hidden = pages.hidden;
    page.value = view.page;
    limit.textContent = 'of ' + format(view.pageCount);
    previous.disabled = current <= 1;
    next.disabled = current >= view.pageCount;
  }

  async function show(requestedPage = 1, trigger) {
    const ticket = ++generation;
    const paging = trigger && pages.contains(trigger);
    const filters = (paging && activeFilters) || {query:query.value.trim(),course:collection.value,kind:type.value};
    list.setAttribute('aria-busy', 'true');
    status.textContent = 'Loading study records…';
    try {
      const options = {...filters, page:requestedPage};
      const view = filters.kind === 'expanded' ? await expandedPracticePage(options) : await libraryPage(options);
      if (ticket !== generation) return;
      const focusedControl = paging && pages.contains(document.activeElement) ? document.activeElement : null;
      activeFilters = filters;
      apply(view);
      if (focusedControl && (focusedControl.disabled || pages.hidden)) {
        (pages.hidden ? status : focusedControl === previous ? next : previous).focus({preventScroll:true});
      }
      if (paging) revealWithinChat(resultBar);
    } catch {
      if (ticket === generation) status.textContent = 'The records could not load. Try searching again.';
    } finally {
      if (ticket === generation) list.removeAttribute('aria-busy');
    }
  }

  search.addEventListener('submit', event => {event.preventDefault(); void show();});
  collection.addEventListener('change', () => void show());
  type.addEventListener('change', () => void show());
  pages.addEventListener('submit', event => {event.preventDefault(); void show(Number(page.value), page);});
  previous.addEventListener('click', () => void show(current - 1, previous));
  next.addEventListener('click', () => void show(current + 1, next));
  pageReturn.addEventListener('click', () => {
    (next.disabled ? previous : next).focus({preventScroll:true});
    revealWithinChat(resultBar);
  });
  try {
    const [manifest,expanded]=await Promise.all([libraryManifest(),expandedManifest().catch(()=>null)]);
    const expandedCount=expanded?.total??0;
    total.textContent = format(manifest.questions) + ' questions · ' +
      format(manifest.practice+expandedCount) + ' practice problems';
    total.hidden = false;
    if(!expandedCount)type.querySelector('option[value="expanded"]').remove();
    for (const item of manifest.collections) {
      const option = document.createElement('option');
      option.textContent = item.course === 'RESOURCES' ? 'Study resources' : item.course;
      option.value = item.course;
      collection.append(option);
    }
    query.value = (initial.query ?? '').slice(0, 1600);
    collection.value = [...collection.options].some(option => option.value === initial.course) ? initial.course : '';
    type.value = [...type.options].some(option=>option.value===initial.kind) ? initial.kind : '';
    await show(initial.page);
    if (host.isConnected && document.activeElement === beforeMount) {
      total.focus({preventScroll:true});
      revealWithinChat(total);
    }
  } catch {
    status.textContent = 'The study library could not load. Reload the page to try again.';
  }
}

export const libraryVersion = 'v4';
const root = '/data/bridgeassist-full/' + libraryVersion + '/';
const stopWords = new Set('a an and are as ask at be but by can could did do does for from give has have help how i if in into is it its me my of on or please should so tell than that the their them then these they this those to use using was we were what when where which why will with would you your'.split(' '));
const cache = new Map();

export function normalizeQuestion(value) {
  return String(value).normalize('NFKC').replace(/[’‘]/g, "'").replace(/[‐‑–−]/g, '-')
    .toLowerCase().replace(/\s+/g, ' ').trim().replace(/[?!.]+$/, '');
}

export function exactQuestion(value) {
  return String(value).normalize('NFC').replace(/[’‘]/g, "'").replace(/\s+/g, ' ').trim().replace(/[?!.]+$/, '');
}

export function libraryTokens(value) {
  const words = normalizeQuestion(value).match(/\d+(?:\.\d+)?|[a-z][a-z0-9]+/g) ?? [];
  return [...new Set(words.filter(word => !stopWords.has(word)).map(word =>
    /^(?:laws|equations|proteins|cells|organelles|chromosomes|reactions|ratios|problems|solutions|questions|moles)$/.test(word)
      ? word.slice(0, -1) : word
  ))];
}

export function bucketFor(value) {
  let hash = 0x811c9dc5;
  for (let i = 0; i < value.length; i++) hash = Math.imul(hash ^ value.charCodeAt(i), 0x01000193);
  return (hash >>> 24).toString(16).padStart(2, '0');
}

async function read(path) {
  if (cache.has(path)) {
    const pending = cache.get(path);
    cache.delete(path);
    cache.set(path, pending);
    return pending;
  }
  const pending = fetch(root + path).then(async response => {
    if (!response.ok) throw Error('Study library file unavailable');
    if (!path.endsWith('.bin')) return response.json();
    return new Response(response.body.pipeThrough(new DecompressionStream('gzip'))).json();
  }).catch(error => {
    if (cache.get(path) === pending) cache.delete(path);
    throw error;
  });
  cache.set(path, pending);
  if (cache.size > 36) cache.delete(cache.keys().next().value);
  return pending;
}

export const libraryManifest = () => read('manifest.json');
export const librarySources = () => read('sources.json');

export async function libraryRecord(position) {
  const {total, shardSize} = await libraryManifest();
  if (!Number.isInteger(position) || position < 0 || position >= total) return null;
  const rows = await read('records/' + Math.floor(position / shardSize) + '.bin');
  return rows[position % shardSize];
}

export async function exactLibraryRecord(query, course = '') {
  const canonical = normalizeQuestion(query);
  if (canonical.length < 12 || canonical.length > 1600) return null;
  const index = await read('exact/' + bucketFor(canonical) + '.bin');
  const stored = Object.hasOwn(index, canonical) ? index[canonical] : undefined;
  if (stored === undefined) return null;
  const positions = Array.isArray(stored) ? stored : [stored];
  const eligible = (await Promise.all(positions.map(async position => ({position, record: await libraryRecord(position)}))))
    .filter(({record}) => !course || record.courses.includes(course) || record.primary_collection === 'RESOURCES');
  const same = eligible.find(({record}) => exactQuestion(record.question) === exactQuestion(query));
  if (same) return same;
  // Capitalization can change genotype and chemical notation in a numerical problem.
  return eligible.length === 1 && eligible[0].record.record_kind === 'question' ? eligible[0] : null;
}

export async function libraryPage({query = '', course = '', kind = '', page = 1, chat = false, exclude = []} = {}) {
  const manifest = await libraryManifest();
  const {total, shardSize, pageSize, collections} = manifest;
  const scope = collections.find(entry => entry.course === course) ?? {start: 0, end: total};
  const skipped = new Set(exclude);
  const within = position => position >= scope.start && position < scope.end && !skipped.has(position);
  const kindList = kind === 'question' || kind === 'practice' ? await read('lists/' + kind + '.bin') : null;
  const terms = libraryTokens(query).slice(0, 20);
  let positions;
  if (terms.length) {
    const buckets = await Promise.all(terms.map(term => read('terms/' + bucketFor(term) + '.bin')));
    const lists = terms.map((term, index) => Object.hasOwn(buckets[index], term) ? buckets[index][term] : [])
      .filter(list => list.length).sort((a, b) => a.length - b.length);
    if (!lists.length) return {results: [], count: 0, page: 1, pageCount: 1};
    const matchingKind = kindList ? new Set(kindList) : null;
    const scores = new Map();
    let bestCoverage = 0;
    for (const list of lists) {
      const weight = Math.log(1 + total / list.length);
      for (const position of list) {
        if (!within(position) || (matchingKind && !matchingKind.has(position))) continue;
        const score = scores.get(position) ?? {position, weight: 0, terms: 0};
        score.weight += weight;
        score.terms++;
        bestCoverage = Math.max(bestCoverage, score.terms);
        scores.set(position, score);
      }
    }
    const threshold = chat ? Math.max(1, terms.length <= 3 ? terms.length : Math.ceil(terms.length * .8))
      : Math.max(1, Math.min(bestCoverage, Math.ceil(lists.length * .55)));
    positions = [...scores.values()].filter(score => score.terms >= threshold)
      .sort((a, b) => b.terms - a.terms || b.weight - a.weight || a.position - b.position)
      .map(score => score.position);
    const exact = chat ? null : await exactLibraryRecord(query, course);
    if (exact && within(exact.position) && (!matchingKind || matchingKind.has(exact.position))) {
      positions = [exact.position, ...positions.filter(position => position !== exact.position)];
    }
  } else if (kindList) {
    positions = kindList.filter(within);
  }
  const count = positions?.length ?? scope.end - scope.start;
  const pageCount = Math.max(1, Math.ceil(count / pageSize));
  const current = Math.min(pageCount, Math.max(1, Math.floor(page) || 1));
  const offset = (current - 1) * pageSize;
  const selected = positions?.slice(offset, offset + pageSize) ??
    Array.from({length: Math.min(pageSize, count - offset)}, (_, index) => scope.start + offset + index);
  const results = await Promise.all(selected.map(async position => {
    const rows = await read('catalog/' + Math.floor(position / shardSize) + '.bin');
    const [id, kind, courseIndex, topic, question, family, topicTerms] = rows[position % shardSize];
    return {position, id, kind, course: collections[courseIndex].course, topic, question, family, topicTerms};
  }));
  return {results, count, page: current, pageCount};
}

const reference = (book, title, section) => ({
  title: 'OpenStax · ' + title,
  url: 'https://openstax.org/books/' + book + '/pages/' + section
});
const chem = (title, section) => reference('chemistry-2e', title, section);
const bio = (title, section) => reference('biology-2e', title, section);

const measurement = chem('Measurements', '1-4-measurements');
const precision = chem('Significant figures and measurement uncertainty', '1-5-measurement-uncertainty-accuracy-and-precision');
const conversions = chem('Unit conversions and dimensional analysis', '1-6-mathematical-treatment-of-measurement-results');
