function html(parent, tag, content) {
  const item = parent.ownerDocument.createElement(tag);
  if (content) item.textContent = content;
  parent.append(item);
  return item;
}

let figureSequence = 0;
const styledDocuments = new WeakSet();

function installMotionStyles(document) {
  if (styledDocuments.has(document) || !document.head) return;
  html(document.head, 'style', '@media(prefers-reduced-motion:reduce){.learner-visual [data-learner-play]{display:none}}');
  styledDocuments.add(document);
}

export function renderLearnerVisual(visual, {document = globalThis.document} = {}) {
  if (!learnerVisuals.includes(visual)) throw TypeError('Choose a visual from the learner visual catalog.');
  installMotionStyles(document);
  const figure = document.createElement('figure');
  figure.className = 'learner-visual';
  figure.setAttribute('data-learner-visual', visual.id);
  const instance = 'learner-visual-' + (++figureSequence);
  const caption = html(figure, 'figcaption', visual.title + ' · Schematic');
  caption.id = instance + '-caption';
  figure.setAttribute('aria-labelledby', caption.id);
  const svg = svgPart(figure, 'svg', {
    viewBox: '0 0 400 210', width: '400', height: '210', role: 'img', focusable: 'false',
    'aria-labelledby': instance + '-title ' + instance + '-description',
    style: 'display:block;width:100%;height:auto;max-width:36rem;margin:.5rem 0'
  });
  const svgTitle = svgPart(svg, 'title', {id: instance + '-title'});
  const svgDescription = svgPart(svg, 'desc', {id: instance + '-description'});
  svgPart(svg, 'rect', {x: 0, y: 0, width: 400, height: 210, rx: 12, fill: palette.panel});
  const artwork = svgPart(svg, 'g', {});
  const stage = html(figure, 'p');
  stage.setAttribute('aria-live', 'polite');
  const explanation = html(figure, 'p');
  const controls = html(figure, 'div');
  controls.setAttribute('role', 'group');
  controls.setAttribute('aria-label', 'Visual playback');
  controls.style.cssText = 'display:flex;flex-wrap:wrap;gap:.5rem';
  const previous = html(controls, 'button', 'Previous');
  const next = html(controls, 'button', 'Next');
  const toggle = html(controls, 'button', 'Play');
  toggle.setAttribute('data-learner-play', '');
  const restart = html(controls, 'button', 'Restart');
  for (const button of [previous, next, toggle, restart]) {
    button.type = 'button';
    button.style.minHeight = '2.75rem';
  }
  const transcript = html(figure, 'details');
  html(transcript, 'summary', 'Read every step');
  const steps = html(transcript, 'ol');
  for (const frame of visual.frames) html(steps, 'li', frame.title + '. ' + frame.description);
  const link = html(html(figure, 'p'), 'a', visual.source.title);
  link.href = visual.source.url;

  const clock = document.defaultView ?? globalThis;
  const reduce = clock.matchMedia?.('(prefers-reduced-motion: reduce)');
  let active = 0;
  let timer = null;
  function show(index, automatic = false) {
    active = index;
    const frame = visual.frames[active];
    artwork.replaceChildren();
    visual.draw(artwork, active);
    svgTitle.textContent = frame.title;
    svgDescription.textContent = frame.description;
    stage.setAttribute('aria-live', automatic ? 'off' : 'polite');
    stage.textContent = (active + 1) + ' of ' + visual.frames.length + ' · ' + frame.title;
    explanation.textContent = frame.description;
    previous.setAttribute('aria-disabled', String(active === 0));
    next.setAttribute('aria-disabled', String(active === visual.frames.length - 1));
  }
  function pause() {
    if (timer !== null) clock.clearTimeout(timer);
    timer = null;
    toggle.textContent = 'Play';
  }
  function tick() {
    if (!figure.isConnected || document.hidden || reduce?.matches) return pause();
    show(active + 1, true);
    if (active === visual.frames.length - 1) return pause();
    timer = clock.setTimeout(tick, 4000);
  }
  function move(direction) {
    pause();
    const nextIndex = active + direction;
    if (nextIndex >= 0 && nextIndex < visual.frames.length) show(nextIndex);
  }
  previous.addEventListener('click', () => move(-1));
  next.addEventListener('click', () => move(1));
  restart.addEventListener('click', () => {
    pause();
    show(0);
  });
  toggle.addEventListener('click', () => {
    if (timer !== null || document.hidden || reduce?.matches) return pause();
    if (active === visual.frames.length - 1) show(0);
    toggle.textContent = 'Pause';
    timer = clock.setTimeout(tick, 4000);
  });
  show(0);
  return figure;
}

import {LearningSession,followUpIntent} from './learning-session.mjs?v=library-5';
import {makePractice,recalculatePractice} from './practice-families.mjs';
import {exactLibraryRecord,exactQuestion,libraryRecord,librarySources} from './full-library.mjs?v=library-4';
import {findChatRecords,practiceRequest} from './library-chat-search.mjs?v=library-5';
import {correctLearnerSpelling} from './learner-tutor.mjs?v=learner-1';
import {exactExpandedPractice,expandedPracticePage,studyRecord} from './expanded-practice.mjs';
const root='/data/bridgeassist-library/';
const stop=new Set('a an the is are was were do does did how what why can could would you i me my it this that of to in on for with and or from at use using please tell get question'.split(' '));
const normal=q=>String(q).normalize('NFKC').replace(/[’‘]/g,"'").replace(/\s+/g,' ').trim().toLowerCase();
const tokens=q=>new Set(normal(q).match(/[a-z]+(?:\+[a-z]+)?|\d+(?:\.\d+)?/g)?.filter(t=>!stop.has(t))??[]);
const acronyms=new Set(['BIOL','CHEM','ATP','DNA','RNA','NAD','NADH','NADPH','FAD','SI','PV','VSEPR','ER']);
const entities=q=>[...String(q).matchAll(/\b(?:AA|Aa|aa|(?:[A-Z][a-z]?\d*){2,})\b/g)].map(m=>m[0]).filter(x=>!acronyms.has(x));
const numberSet=q=>new Set([...String(q).matchAll(/(?<![\w.])-?\d+(?:\.\d+)?/g)].map(m=>String(Number(m[0]))));
export function rankLibrary(query,index,course=''){
 const q=normal(query),qt=tokens(query),qe=entities(query);
 return index.filter(r=>!course||r.courses.includes(course)||r.primary_collection==='RESOURCES').map(r=>{
  const exact=q===normal(r.question)||(r.aliases??[]).some(a=>normal(a)===q);
  const rt=tokens(r.question+' '+r.topic),re=entities(r.question);
  if(qe.some(e=>!re.includes(e)))return {record:r,score:0,coverage:0,exact:false};
  let shared=0;for(const t of qt)if(rt.has(t))shared++;
  const coverage=qt.size?shared/qt.size:0;
  return {record:r,score:exact?100:coverage*7+shared*.25+(course&&r.courses.includes(course)?0.5:0),coverage,exact};
 }).sort((a,b)=>b.score-a.score);
}
export function createLibraryTutor({fetcher=fetch,fullRelease=false}={}){
 let loading,sources,index,version=0,selectedCourse='';const shards=new Map();
 let activeSources, exampleTopic, exercise, awaitingTopic=false, pendingWorked=false, examples=new Set();
 const session=new LearningSession({recalculate:recalculatePractice});
 async function matchExact(query,course){
  const original=await exactLibraryRecord(query,course).catch(()=>null);
  if(original)return original;
  return /\d/.test(query)?await exactExpandedPractice(query,course).catch(()=>null):null;
 }
 async function extraPractice(options){
  const page=await expandedPracticePage({query:options.topic,course:options.course,exclude:options.exclude}).catch(()=>null);
  if(!page?.results.length)return [];
  return Promise.all(page.results.slice(0,options.count).map(async item=>
   ({...item,record:await studyRecord(item.position),requestedTopic:options.topic,phrase:true})));
 }
 async function json(path){const response=await fetcher(root+path);if(!response.ok)throw Error('Learning library unavailable');return response.json();}
 function ready(){return loading??=Promise.all([json('index.json'),json('sources.json')]).then(([a,b])=>{index=a;sources=b;}).catch(error=>{loading=null;throw error;});}
 function reset(){version++;session.reset();activeSources=null;exampleTopic='';exercise=false;awaitingTopic=false;pendingWorked=false;examples.clear();}
 async function startFull(record,ticket,{asExercise=false,worked=false}={}){
  const fullSources=await librarySources();
  if(ticket!==version)return null;
  activeSources=fullSources;
  exercise=asExercise;
  const reply={...session.start(record),sources:fullSources,record,exercise};
  if(worked){
   const solution=await session.respond('Show the complete worked solution');
   return {...solution,sources:fullSources,record,exercise};
  }
  if(asExercise){
   reply.text='Try this '+(record.record_kind==='practice'?'practice problem.':'concept question.');
   reply.prompt=null;
  }
  return reply;
 }
 async function getRecord(entry){if(!shards.has(entry.shard))shards.set(entry.shard,json(entry.shard).catch(error=>{shards.delete(entry.shard);throw error;}));return (await shards.get(entry.shard)).find(r=>r.id===entry.id);}
 return {
  reset,
  hasPractice:()=>session.record?.record_kind==='practice',
  async openExact(query,course=''){
   const ticket=version;
   const match=await matchExact(query,course);
   if(ticket!==version||!match)return null;
   selectedCourse=course;
   return startFull(match.record,ticket);
  },
  async choose(item,asExercise){
   if(asExercise&&item.requestedTopic!==exampleTopic){
    exampleTopic=item.requestedTopic;
    examples.clear();
    examples.add(item.position);
   }
   return startFull(item.record,version,{asExercise,worked:item.worked});
  },
  async findRelated(query,course='',asResource=false){
   const topic=asResource?query.replace(/^.*?\b(?:find|locate|looking for|resources? for)\b\s*/i,''):query;
   const ticket=version;
   const matches=await findChatRecords({topic,course:asResource?'RESOURCES':course,kind:'question',count:3});
   if(ticket!==version||!matches.length)return null;
   if(matches.length===1&&matches[0].confidence>0&&!/\d/.test(topic))return startFull(matches[0].record,ticket);
   return {kind:'matches',text:'These saved questions may help. Choose one to open its explanation.',matches};
  },
  async open(position,course='',asExercise=false){
   reset();selectedCourse=course;
   const ticket=version;
   const record=await studyRecord(position);
   return record?startFull(record,ticket,{asExercise}):null;
  },
  async respond(query,course=''){
   const intent=/^(?:what (?:is|are)|define)\b/i.test(query.trim())&&!/\b(?:this|that|these|those)\b/i.test(query)?null:followUpIntent(query);
   const named=/\b(BIOL|CHEM)\s*(1405|1406|1407|1411)\b/i.exec(query);
   const effective=named?named[1].toUpperCase()+' '+named[2]:course||(intent?selectedCourse:'');
   if(effective!==selectedCourse){reset();selectedCourse=effective;}
   const beforeLoad=version;
   const search=named?query.replace(named[0],'').trim():query;
   const corrected=fullRelease?correctLearnerSpelling(search):search;
   const request=fullRelease?(practiceRequest(corrected)??(awaitingTopic&&!intent?{topic:corrected,count:1,worked:pendingWorked}:null)):null;
   if(fullRelease&&(!session.record||!intent)){
    const match=await matchExact(query,effective)??(named?await matchExact(search,effective):null);
    if(beforeLoad!==version)return null;
    if(match)return startFull(match.record,beforeLoad);
   }
   if(request&&(!intent||request.topic||request.another)){
    const topic=request.topic||exampleTopic||session.record?.topic;
    if(!topic){awaitingTopic=true;pendingWorked=request.worked;return {kind:'clarify',text:'What topic should the practice question cover?'};}
    awaitingTopic=false;
    if(request.topic&&normal(request.topic)!==normal(exampleTopic??''))examples.clear();
    exampleTopic=topic;
    const options={topic,course:effective,exclude:[...examples],count:request.count};
    const expanded=request.another?await extraPractice(options):[];
    const practices=expanded.length?expanded:await findChatRecords({...options,kind:'practice'});
    const focused=practices.filter(item=>item.phrase);
    const concepts=focused.length?[]:await findChatRecords({...options,kind:'question'});
    const checks=focused.length?focused:concepts.length?concepts:practices.length?practices:await extraPractice(options);
    if(beforeLoad!==version)return null;
    if(!checks.length)return {kind:'clarify',text:examples.size?
     'I ran out of close matches for this topic. Name a more specific concept or choose another topic.':
     'I couldn’t find a close practice question for that wording. Try naming the specific concept or method.'};
    for(const item of checks)examples.add(item.position);
    if(checks.length===1)return startFull(checks[0].record,beforeLoad,{asExercise:true,worked:request.worked});
    return {kind:'matches',text:request.worked?'Choose a question to see its worked solution.':'Choose a question to try. You can ask for a hint or see the worked solution.',
     matches:checks.map(item=>({...item,worked:request.worked})),exercise:true};
   }
   await ready();if(beforeLoad!==version)return null;
   const exact=index.find(r=>(!effective||r.courses.includes(effective)||r.primary_collection==='RESOURCES')&&
    (r.record_kind==='practice'?exactQuestion(r.question)===exactQuestion(search):
     normal(r.question)===normal(search)||(r.aliases??[]).some(a=>normal(a)===normal(search))));
   if(exact){const record=await getRecord(exact);if(beforeLoad!==version)return null;activeSources=null;exercise=false;return {...session.start(record),sources,record};}
   if(/^(?:what (?:is|are)|define)\b/i.test(search)&&!/[0-9]/.test(search)&&!intent){session.reset();return null;}
   if(intent&&session.record){const response=await session.respond(query);return response?{...response,sources:activeSources??sources,record:session.record,exercise}:null;}
   if(intent&&!session.record&&!['rounding','units','check-answer'].includes(intent))return {...await session.respond(query),sources:sources??{},record:null};
   const ticket=++version;
   await ready();if(ticket!==version)return null;
   const candidates=rankLibrary(corrected,index,effective),best=candidates[0],second=candidates[1];
