  graph=[input('amount','solute amount','amount','mol'),input('volume-ml','final solution volume','volumeML','mL'),node('conversion','defined milliliters per liter','1000','mL/L','provided_constant','Milli means one thousandth: 1000 mL = 1 L is exact.'),node('volume-l','solution volume in liters',liters,'L','calculated','Convert the final solution volume to liters.',['volume-ml','conversion'],`${p.volumeML} mL × 1 L / 1000 mL = ${liters} L`),node('concentration','molarity',answer,unit,'calculated','Divide moles of solute by liters of final solution.',['amount','volume-l'],`${p.amount} mol / ${liters} L = ${answer} mol/L`)];
