const requests = new WeakMap();

function load(fetcher, path) {
  if (!requests.has(fetcher)) requests.set(fetcher, new Map());
  const cache = requests.get(fetcher);
  if (!cache.has(path)) {
    const promise = fetcher(path, {credentials: 'same-origin', signal: AbortSignal.timeout(3500)}).then(response => {
      if (!response.ok) throw Error('The study image catalog did not load.');
      return response.json();
    }).catch(error => {
      cache.delete(path);
      throw error;
    });
    cache.set(path, promise);
  }
  return cache.get(path);
}

function https(value) {
  try {
    const url = new URL(value);
    return url.protocol === 'https:' && !url.username && !url.password ? url.href : null;
  } catch {
    return null;
  }
}

function viewable(asset) {
  return asset?.reviewState === 'approved-display' && localImage.test(asset.image) && https(asset.source) &&
    (asset.rightsStatus === 'project-owned' || https(asset.rights)) &&
    asset.alt && asset.title && asset.caption && asset.creator &&
    Number.isInteger(asset.width) && Number.isInteger(asset.height) && asset.width > 0 && asset.height > 0;
}

export async function findStudyImages({topic = '', prompt = '', course = '', limit = 2, fetcher = fetch} = {}) {
  const query = String(prompt).normalize('NFKC');
  if (/\b(?:handouts?|worksheets?|pdf|download|resource links?)\b/i.test(query)) return [];
  const terms = categories.filter(([, pattern]) => pattern.test(query)).map(([slug, , tag]) => tag ?? slug);
  const topicTag = topicNames.get(topic) ?? topic;
  const validTags = [...new Set([...terms, topicTag].filter(value => /^[a-z0-9-]+$/.test(value)))];
  if (!validTags.length) return [];

  const inventory = await load(fetcher, manifestPath).catch(() => null);
  if (inventory?.version !== 1) return [];
  const results = new Map();
  const max = Math.min(4, Math.max(1, Number.isInteger(limit) ? limit : 2));
  for (const tag of validTags) {
    const first = inventory.objectives?.[tag]?.shards?.[0];
    if (!shardPath.test(first)) continue;
    const assets = await load(fetcher, first).catch(() => null);
    if (!Array.isArray(assets)) continue;
    for (const asset of assets) {
      if (!viewable(asset) || (course && asset.courses && !asset.courses.includes(course))) continue;
      results.set(asset.assetId, asset);
      if (results.size === max) return [...results.values()];
    }
  }
  return [...results.values()];
}

export function renderStudyImage(asset, {document = globalThis.document} = {}) {
  if (!viewable(asset)) throw TypeError('Choose an approved image from the study catalog.');
  const figure = document.createElement('figure');
  figure.className = 'study-image';
  const make = (tag, text, parent = figure) => {
    const item = document.createElement(tag);
    if (text) item.textContent = text;
    parent.append(item);
    return item;
  };
  const img = make('img');
  img.width = asset.width;
  img.height = asset.height;
  img.alt = asset.alt;
  img.loading = 'lazy';
  img.decoding = 'async';
  img.style.cssText = 'display:block;max-width:100%;height:auto;margin-inline:auto';
  img.src = asset.image;
  const caption = make('figcaption');
  make('strong', asset.title, caption);
  make('p', asset.caption, caption);
  const credit = make('small', '', caption);
  make('span', asset.kind + ' · ' + asset.creator + ' · ', credit);
  const source = make('a', 'Original source', credit);
  source.href = https(asset.source);
  if (asset.rights) {
    make('span', ' · ', credit);
    make('a', asset.license ?? 'Rights statement', credit).href = https(asset.rights);
    make('p', asset.modification, caption);
  }
  return figure;
}

const SVG = 'http://www.w3.org/2000/svg';
const ink = '#172637';
const muted = '#425973';
const teal = '#16687d';
const purple = '#733f9c';
const berry = '#ae3f65';
