const white = '#ffffff';
const bio = 'https://openstax.org/books/biology-2e/pages/';
const chem = 'https://openstax.org/books/chemistry-2e/pages/';
const frame = (title, description) => ({title, description});

function element(parent, tag, attributes, label = '') {
  const node = parent.ownerDocument.createElementNS(SVG, tag);
  for (const [key, value] of Object.entries(attributes)) node.setAttribute(key, value);
  if (label) node.textContent = label;
  parent.append(node);
  return node;
}

function label(svg, x, y, content, options = {}) {
  element(svg, 'text', {
    x, y, fill: ink, 'text-anchor': 'middle', 'font-size': 14,
    'font-family': 'system-ui,sans-serif', ...options
  }, content);
}

function line(svg, d, stroke = ink, options = {}) {
  element(svg, 'path', {
    d, fill: 'none', stroke, 'stroke-width': 2.4, 'stroke-linecap': 'round', 'stroke-linejoin': 'round', ...options
  });
}

function rect(svg, x, y, width, height, fill, stroke = 'none') {
  element(svg, 'rect', {x, y, width, height, rx: 10, fill, stroke, 'stroke-width': 2});
}

function dot(svg, x, y, radius, fill) {
  element(svg, 'circle', {cx: x, cy: y, r: radius, fill});
}

function arrow(svg, x, y, endX, color = teal) {
  const base = endX - 6 * Math.sign(endX - x);
  line(svg, 'M' + x + ' ' + y + ' H' + endX + ' M' + base + ' ' + (y - 4) + ' L' + endX + ' ' + y + ' L' + base + ' ' + (y + 4), color);
}

function drawProcess(svg, nodes, active, footer) {
  const width = nodes.length === 3 ? 106 : 83;
  const step = nodes.length === 3 ? 125 : 97;
  const left = (400 - width - step * (nodes.length - 1)) / 2;
  nodes.forEach(([title, note, color], index) => {
    const x = left + index * step;
    const selected = active === index;
    rect(svg, x, 67, width, 78, selected ? soft : white, selected ? color : '#a8bfd3');
    if (index < nodes.length - 1) arrow(svg, x + width + 3, 106, x + step - 3, muted);
    label(svg, x + width / 2, 98, title, {'font-size': 12, 'font-weight': 700, fill: selected ? color : ink});
    label(svg, x + width / 2, 121, note, {'font-size': 12});
  });
  label(svg, 200, 177, footer, {fill: muted, 'font-size': 13});
}

function drawPlantCycle(svg, stage) {
  const stages = [
    ['Sporophyte', '2n', teal], ['Spore', 'n', purple], ['Gametophyte', 'n', purple], ['Zygote', '2n', teal]
  ];
  const footer = ['Meiosis makes spores', 'Mitosis grows the gametophyte', 'Gametes fuse during fertilization', 'Mitosis grows the sporophyte', 'Moss and fern share the cycle'][stage];
  drawProcess(svg, stages, stage < 4 ? stage : -1, footer);
  const arrowLabels = [['Meiosis', 107], ['Mitosis', 204], ['Fertilization', 301]];
  for (const [name, x] of arrowLabels) label(svg, x, 50, name, {'font-size': 11, fill: muted});
  line(svg, 'M345 146 V158 H55 V149 M51 154 L55 149 L59 154', muted, {'stroke-width': 1.7});
  if (stage === 4) {
    label(svg, 151, 18, 'Leafy moss → gametophyte', {fill: purple, 'font-size': 12});
    label(svg, 304, 18, 'Fern frond → sporophyte', {fill: teal, 'font-size': 12});
  }
}

function drawRespirationBudget(svg, stage) {
  const nodes = [['Glycolysis', '2 ATP net', teal], ['Pyruvate', '0 ATP', teal], ['Citric cycle', '2 ATP equiv.', purple], ['Oxid. phos.', '≈ 26–28 ATP', berry]];
  drawProcess(svg, nodes, stage, [
    'Also produces 2 NADH per glucose',
    'Oxidizing both pyruvates produces 2 NADH',
    'Two turns add 6 NADH and 2 FADH₂',
    'O₂ accepts electrons · total ≈ 30–32 ATP'
  ][stage]);
  label(svg, 200, 34, 'Estimated yield per glucose', {'font-weight': 700, 'font-size': 16});
}

function drawCellWalls(svg, stage) {
  label(svg, 103, 36, 'Red blood cell', {'font-weight': 700});
