  label(svg, 296, 190, ['Wall remains in place', 'Pressure rises', 'Turgid'][stage], {fill: '#256548'});
}

function populationPath(exponential) {
  return Array.from({length: 45}, (_, i) => {
    const time = 20 * i / 44;
    const population = exponential ? 200 * Math.exp(0.1 * time) : 1000 / (1 + 4 * Math.exp(-0.1 * time));
    return (i ? 'L' : 'M') + (55 + 295 * time / 20).toFixed(1) + ' ' + (163 - 128 * population / 1500).toFixed(1);
  }).join(' ');
}

function drawPopulation(svg, stage) {
  const k = 163 - 128 * 1000 / 1500;
  line(svg, 'M55 25 V163 H356');
  line(svg, 'M55 ' + k + ' H355', muted, {'stroke-width': 1.3, 'stroke-dasharray': '3 5'});
  label(svg, 372, k + 5, 'K', {'font-size': 12, fill: muted});
  line(svg, populationPath(false), teal, {'stroke-width': stage === 1 ? 4 : 2.6});
  line(svg, populationPath(true), berry, {'stroke-width': stage === 0 ? 4 : 2.6, 'stroke-dasharray': '7 4'});
  dot(svg, 55, 163 - 128 * 200 / 1500, 4, ink);
  label(svg, 31, 92, 'Population', {transform: 'rotate(-90 31 92)', 'font-size': 12});
  label(svg, 199, 181, 'Time', {'font-size': 12});
  label(svg, 113, 201, 'Solid · logistic', {'font-size': 12, fill: teal});
  label(svg, 284, 201, 'Dashed · exponential', {'font-size': 12, fill: berry});
  if (stage === 2) label(svg, 152, 40, 'At N = 200: 16 vs 20 per year', {'font-size': 12, fill: ink});
}

function particle(svg, x, y, kind, opacity = 1) {
  const h = kind === 'H₂';
  const color = h ? teal : berry;
  const group = element(svg, 'g', {opacity});
  dot(group, x - 5, y, h ? 5 : 7, color);
  dot(group, x + 5, y, h ? 5 : 7, color);
}

function drawLimiting(svg, stage) {
  const xs = [75, 103, 131, 159, 187, 215];
  label(svg, 200, 36, '2 H₂ + O₂ → 2 H₂O', {'font-size': 17, 'font-weight': 700});
  label(svg, 37, 84, 'H₂', {'font-weight': 700, fill: teal});
  label(svg, 37, 128, 'O₂', {'font-weight': 700, fill: berry});
  if (stage < 2) {
    xs.forEach((x, i) => particle(svg, x, 79, 'H₂', stage === 1 && i >= 4 ? 0.25 : 1));
    [75, 103].forEach(x => particle(svg, x, 123, 'O₂'));
  } else {
    [75, 103].forEach(x => particle(svg, x, 79, 'H₂'));
    label(svg, 87, 128, '0', {fill: berry, 'font-weight': 700});
  }
  if (stage === 2) {
    label(svg, 294, 83, '4 model H₂O', {'font-weight': 700});
    for (const x of [252, 279, 306, 333]) {
      dot(svg, x, 119, 6, berry);
      dot(svg, x - 6, 125, 4, teal);
      dot(svg, x + 6, 125, 4, teal);
    }
  } else {
    label(svg, 313, 92, ['Model counts', '2 H₂ per O₂'][stage], {'font-size': 13, fill: muted});
    if (stage === 1) label(svg, 313, 124, '2 batches', {'font-size': 13, fill: ink});
  }
  label(svg, 200, 177, ['Starting particle model · 6 H₂ and 2 O₂', 'Only two complete reaction batches are possible', 'O₂ is used up · H₂ remains'][stage], {'font-size': 13, fill: muted});
}

function drawRealGas(svg, stage) {
  line(svg, 'M55 25 V158 H358');
  line(svg, 'M55 98 H350', muted, {'stroke-width': 1.4, 'stroke-dasharray': '5 4'});
  label(svg, 39, 103, '1', {'font-size': 13});
  label(svg, 24, 39, 'Z', {'font-weight': 700});
  label(svg, 240, 181, 'Increasing pressure →', {'font-size': 13});
  if (stage > 0) {
    line(svg, stage === 1 ? 'M55 98 C107 99 135 135 242 129' : 'M55 98 C110 99 153 154 236 120 C282 101 324 65 347 34', berry, {'stroke-width': 3});
  }
  label(svg, 292, 91, 'Ideal gas', {'font-size': 12, fill: muted});
  if (stage === 1) label(svg, 139, 147, 'Attractions dominate', {'font-size': 12, fill: berry});
  if (stage === 2) label(svg, 230, 39, 'Molecular volume matters', {'font-size': 12, fill: berry});
  label(svg, 73, 180, 'Schematic', {'font-size': 11, fill: muted});
}

