const defaultBase = '/data/tutoring-archive/v1/';
const courseIds = ['BIOL 1406', 'BIOL 1407', 'CHEM 1411'];

export function normalizeArchiveQuestion(input) {
  return String(input ?? '').normalize('NFC').replace(/[’‘]/g, "'").replace(/[“”]/g, '"')
    .replace(/\s+/gu, ' ').trim().replace(/\s*[?!]+$/, '')
    .replace(/^[A-Z](?=[a-z]{2})/, letter => letter.toLowerCase());
}

export function archiveBucket(value) {
  let hash = 2166136261;
  for (let index = 0; index < value.length; index++) {
    hash = Math.imul(hash ^ value.charCodeAt(index), 16777619);
  }
  return (hash & 255).toString(16).padStart(2, '0');
}

const command = input => /^(?:show|open|start)(?: me)? (?:a )?(?:(BIOL 1406|BIOL 1407|CHEM 1411) )?(?:tutoring|study) (?:chat|conversation)s?[?.!]*$/i.exec(input);
const selector = input => /^open tutoring example ([a-zA-Z0-9_-]{1,120})[?.!]*$/i.exec(input);

export function isTutoringArchiveCommand(input) {
  const text = String(input ?? '').trim();
  return Boolean(command(text) || selector(text));
}

export function createTutoringArchive({fetcher=globalThis.fetch, base=defaultBase, seed=null}={}) {
  const cache = new Map();
  let active = null;
  let initial = seed;
  let generation = 0;

  function reset() {
    active = null;
    initial = null;
    generation++;
  }

  async function json(file) {
    if (cache.has(file)) {
      const cached = cache.get(file);
      cache.delete(file);
      cache.set(file,cached);
      return cached;
    }
    const loading = (async () => {
      const response = await fetcher(base + file, {signal: AbortSignal.timeout(4500)});
      if (!response.ok) return null;
      if (!file.endsWith('.bin')) return response.json();
      const bytes = new Uint8Array(await response.arrayBuffer());
      if (bytes[0] !== 31 || bytes[1] !== 139) return JSON.parse(new TextDecoder().decode(bytes));
      if (typeof DecompressionStream !== 'function') return null;
      const body = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
      return new Response(body).json();
    })().catch(() => null);
    cache.set(file, loading);
    if (cache.size > 24) cache.delete(cache.keys().next().value);
    const value = await loading;
    if (!value && cache.get(file) === loading) cache.delete(file);
    return value;
  }

  async function lookup(id) {
    const shard = await json('record/' + archiveBucket(id) + '.bin');
    return shard && Object.hasOwn(shard, id) ? shard[id] : null;
  }

  function canContinue(input, course='') {
    if (isTutoringArchiveCommand(input)) return true;
    if (!active || (course && active.info.course !== course)) return false;
    const expected = active.record.turns[active.next]?.[0];
    return Boolean(expected && normalizeArchiveQuestion(expected) === normalizeArchiveQuestion(input));
  }

  function state() {
    return active ? {id:active.record.id, next:active.next} : null;
  }

  function reply(record, info, position, showQuestion=false) {
    active = {record, info, next:position + 1};
    const [question,text] = record.turns[position];
    const next = record.turns[position + 1]?.[0];
    return {
      topic:record.id, title:record.topic, text, links:info.links,
      actions:next ? [[next,next]] : [], intent:'archived-chat', course:info.course,
      archiveCase:record.id, archiveTurn:position, exampleQuestion:showQuestion ? question : undefined
    };
  }

  async function respond(raw, course='') {
    const serial = ++generation;
    const input = String(raw ?? '').trim();
    const pendingSeed = initial;
    initial = null;
    const selection = selector(input);
    const menu = command(input);
    if (menu) {
      const preferred = menu[1]?.toUpperCase() || course;
      const manifest = await json('manifest.json');
      if (!manifest || serial !== generation) return null;
      const actions = courseIds.includes(preferred)
        ? Object.entries(manifest.demos).filter(([unit]) => manifest.units[unit]?.course === preferred)
          .map(([unit,id]) => [manifest.units[unit].title,'Open tutoring example ' + id])
        : courseIds.map(item => [item,'Show a ' + item + ' tutoring chat']);
      return {topic:'tutoring-archive', title:'Choose a tutoring conversation',
        text:courseIds.includes(preferred) ? 'Pick a topic to start a saved study conversation.' : 'Pick a course to see study conversations.',
        links:[], actions, intent:'archived-chat'};
    }

    if (selection || pendingSeed?.id) {
      const id = selection?.[1] ?? pendingSeed.id;
      const record = await lookup(id);
      const manifest = record && await json('manifest.json');
      const info = manifest?.units[record?.unit];
      if (serial !== generation) return null;
      if (record && info && selection && Object.values(manifest.demos).includes(id)) {
        return reply(record, info, 0, true);
      }
      if (record && info && !selection && Number.isInteger(pendingSeed.next)
          && pendingSeed.next >= 1 && pendingSeed.next <= record.turns.length) {
        active = {record, info, next:pendingSeed.next};
      }
      if (selection) return null;
    }

    if (canContinue(input,course)) return reply(active.record, active.info, active.next);
    const key = normalizeArchiveQuestion(input);
    if (key.length < 4 || key.length > 1200) return null;
    const index = await json('question/' + archiveBucket(key) + '.bin');
    const matches = index && Object.hasOwn(index,key) ? index[key] : null;
    if (!matches || serial !== generation) return null;
    const id = course ? matches[course] : Object.keys(matches).length === 1 ? Object.values(matches)[0] : null;
    if (!id) return null;
    const record = await lookup(id);
    const manifest = record && await json('manifest.json');
    const info = manifest?.units[record?.unit];
    if (!record || !info || serial !== generation || (course && info.course !== course)) return null;
    if (normalizeArchiveQuestion(record.turns[0][0]) !== key) return null;
    return reply(record,info,0);
  }

  return {respond, canContinue, state, reset};
}
